import{O as e,U as t,W as n}from"./CYYkGqRJ.js";var r=[`en`,`fr`,`tl`,`pa`,`zh-Hans`,`zh-Hant`],i={en:{native:`English`,english:`English`,htmlLang:`en`},fr:{native:`Français`,english:`French (Canadian)`,htmlLang:`fr-CA`},tl:{native:`Tagalog`,english:`Tagalog`,htmlLang:`tl`},pa:{native:`ਪੰਜਾਬੀ`,english:`Punjabi`,htmlLang:`pa`},"zh-Hans":{native:`简体中文`,english:`Chinese (Simplified)`,htmlLang:`zh-Hans`},"zh-Hant":{native:`繁體中文`,english:`Chinese (Traditional)`,htmlLang:`zh-Hant`}},a=`audit_lang`,o=`lang`;function s(e){return!!e&&r.includes(e)}function c(e){let t=e.toLowerCase();if(t.startsWith(`zh`))return t.includes(`hant`)||t.startsWith(`zh-hk`)||t.startsWith(`zh-tw`)||t.startsWith(`zh-mo`)?`zh-Hant`:`zh-Hans`;let n=t.split(`-`)[0];return s(n)?n:null}function l(){let e=new URL(window.location.href).searchParams.get(o);if(s(e))return e;try{let e=localStorage.getItem(a);if(s(e))return e}catch{}let t=navigator.languages??[navigator.language];for(let e of t){let t=c(e);if(t)return t}return`en`}var u=n(`en`);{t(u,l(),!0);let n=new URL(window.location.href);n.searchParams.get(o)!==e(u)&&(n.searchParams.set(o,e(u)),window.history.replaceState({},``,n.toString()))}function d(e){if(!s(e))return;t(u,e,!0);try{localStorage.setItem(a,e)}catch{}let n=new URL(window.location.href);n.searchParams.set(o,e),window.history.replaceState({},``,n.toString())}var f={get current(){return e(u)}},p={en:{selector:{label:`Choose language`},disclaimer:{text:`This site has been translated by AI. Some content may still appear in English while translations are in progress. If you notice errors or would like to help translate this project, please %s.`,link_label:`contact us`},opener:{heading:`Who's this for?`,body:`Us. All of us. Rural, Urban, curious, wonk, journalist, lawyer, academic, politician — all of us. Because it impacts all of us. Whether or not you like the party in power, what the split commission produced has never been done before. And it's given us the opportunity to peer inside the machine in ways we never could before. Now we can establish a baseline — a series of tests, and everything that comes after can be graded on it. Let me show you what I found.`},stakes:{q1:{heading:`Is the proposed map a gerrymander?`,body:`"Gerrymander" is not a term Canadian courts use. But if it were — in the everyday sense most people mean by it — the evidence in this audit would reasonably support calling the <em>minority proposal</em>, if enacted, a heavily gerrymandered map. Every structural test this audit runs flags the <em>minority proposal</em>; none flag the alternative (the <em>majority proposal</em>).`,footnote:`The "majority" and "minority" names come from a 3–2 split among the Electoral Boundaries Commission (chaired by Justice Miller), which produced two competing proposals rather than a single recommendation. A separate MLA committee chaired by Brandon Lunty — a Premier-appointed MLA — is now choosing between them before the November 2026 deadline.`},q2:{heading:`What does "gerrymander" mean in Canadian law?`,body:`There isn't one. The Canadian test is different: whether the boundaries give voters <em>effective representation</em> under section 3 of the Charter. The minority proposal raises serious questions under the effective-representation standard; only a judge can answer them definitively, and no one has asked one yet.`},q3:{heading:`What's at stake for Albertans?`,body:`At a 50/50 provincial vote, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. That imbalance matters because at 58 of 87 seats (a two-thirds supermajority) the governing party unlocks extraordinary procedural powers. It can waive standard notice periods and push public bills through multiple legislative stages in a single day, bypassing the deliberation checks the legislature normally relies on. Whether the minority proposal's tilt is large enough to push one party past that 58-seat threshold at vote shares <em>other</em> than 50/50 is a question this audit has not yet tested. Whether that imbalance is acceptable is a question for Albertans, not for this audit.`},cta_law:`Read the legal context →`,cta_methods:`See how we tested →`,scorecard_h:`The scorecard`,scorecard_fig_alt:`Scatter plot: efficiency gap on the horizontal axis, count of structural tests failed on the vertical axis. The 2019 enacted map and the 2026 majority map cluster in the safe lower-left corner. The 2026 minority map appears alone in the upper-right outlier region.`,scorecard_fig_caption:`Both lanes on one picture. Horizontal: how skewed the partisan-fairness number is (right = more UCP-favoured). Vertical: how many of five structural-fairness tests the map fails. Bottom-left is the safe corner where neutral procedures routinely land; the upper-right is the outlier region. The 2019 enacted map and the 2026 majority sit in the safe corner. The 2026 minority sits alone in the outlier region.`,scorecard_intro:`Two independent measurements applied to both maps under the same pre-registered thresholds. Structure (left column) uses only the shape of the lines — no election results. Numbers (right column) tests how the lines convert votes into seats. Both lanes reach the same conclusion.`,scorecard_col_b:`Structure (geometry only, no votes)`,scorecard_col_c:`Numbers (vote-dependent)`,scorecard_r1_a:`Majority 2026`,scorecard_r1_b:`passes — crosses no structural threshold`,scorecard_r1_c:`inside the normal range on every measure`,scorecard_r2_a:`Minority 2026`,scorecard_r2_b:`fails 4 of 5 structural thresholds (anchoring neutral for both)`,scorecard_r2_c:`outlier on all four partisan-fairness measures — <code>seats@50/50</code> 51.7% at the 99.99th percentile; fewer than 100 of 1,010,000 neutral maps reach this`,scorecard_close:`Two independent measurements, one answer. The convergence is the audit's strongest single signal.`},head:{title:`Alberta Electoral Boundary Audit`,meta_description:`Statistical audit of Alberta's 2026 electoral boundary commission — 1,010,000 neutral maps, official Elections Alberta shapefiles, pre-registered tests.`},nav:{skip_to_content:`Skip to content`,home_aria:`Back to top`,theme_aria:`Toggle dark/light mode`,theme_title:`Toggle dark mode`,nav_aria:`Open table of contents`,drawer_top:`↑ Top`,stakes:`Stakes`,findings:`Findings`,history:`History`,reform:`Reform`,notes:`Notes`,group_overview:`Overview`,group_audit:`The audit`,group_context:`Context`,group_forward:`Going forward`,group_apparatus:`Apparatus`,why:`Why does this matter?`,map:`The map at a glance`,split:`How the commission broke`,litmus:`1,010,000-Map Litmus Test`,crack_pack:`Cracking, packing, draining`,for_you:`What this means for you`,impact:`Impact on the ground`,gerrymanders:`Clean gerrymanders`,history_full:`A history of gerrymandering`,canada:`Canada's different`,november:`November`,lunty:`Lunty`,invisible:`Invisible`,suggestions:`Reform suggestions`,retractions:`Retractions`,references:`References`,resources:`Resources`,technical:`Technical resources`},hero:{h1:`Alberta Electoral Boundary Audit`,subtitle:`Alberta's commission produced two riding maps in 2026. This audit compared them — using the same tests, applied equally to both — to ask whether they treat voters the same way.`,badge:`Official Elections Alberta maps — Published May 2026`,cover_note:`Click to zoom and explore all three boundary proposals simultaneously. Pin the viewport and flip between maps — boundaries shift, voters stay put. Scroll down for the analysis.`,cover_note_1:`This map is the best way in. Click it to zoom and explore. The buttons at the top switch between the minority map, the majority map, and the 2019 enacted boundaries — or layer all three to see exactly where they diverge. <strong>Detail</strong> colours each polling area by how people voted in 2023; <strong>Trend</strong> adds partisan shading by district (blue UCP, orange NDP); <strong>Lines</strong> toggles boundaries on and off. <strong>Find</strong> jumps to any riding by name.`,cover_note_2:`Try locking the viewport and flipping between maps — watch a boundary shift while the voters underneath stay still. The whole question, in one gesture.`,cover_note_3:`When you're done exploring, scroll down for the summary. For the full technical analysis, see the Resources section. All data is official Elections Alberta shapefiles and other government and open-source records.`,image_alt:`Alberta electoral district maps — minority commission proposal, coloured by 2023 vote`,map_hint:`Click to explore interactively`,btn_title:`Click to open interactive map`,btn_aria:`Click to explore interactively`},boundary:{heading:`What this audit can and can't tell you`,can_1:`Fewer than 1 in 14.5 million randomly generated comparison maps produced patterns as extreme as the minority proposal on all four statistical measures combined.`,can_2:`The minority proposal fails 4 of 5 pre-registered structural tests; the fifth (anchoring) is neutral — both maps fall within the Canadian norm. The majority proposal fails 0 of the 4 firing.`,can_3:`These results are consistent with maps that produce strong partisan effects, and inconsistent with what the random comparison set produces.`,cant_1:`The audit does <strong>not</strong> establish that any commissioner intended the partisan effects it measures. Boundary geometry cannot reveal intent.`,cant_2:`The audit does <strong>not</strong> predict what the Lunty committee will choose, what the November 2026 vote will be, or how Albertans will react.`,cant_3:`The audit does <strong>not</strong> predict how a court would rule if a Charter challenge were brought against either proposal.`,cant_4:`The audit does <strong>not</strong> tell any individual voter what position to take or what to do with this information. The choice is yours.`},editorial_intro:{heading:`What is redistricting, and why it matters`,p1:`Every voter in Alberta lives in an <em>electoral district</em> — a slice of the province that elects one person to the legislature. There are 87 districts. Each district elects one MLA. When you cast a ballot in a provincial election, you are choosing the MLA for the district you live in. For most Albertans, that is the whole connection to the legislature: one MLA, one district, one vote.`,p2:`Those district lines are not permanent. People move, neighbourhoods grow, rural areas thin out, cities sprawl. Every eight to ten years, Alberta is supposed to redraw the lines so each district is roughly the right size and reflects the way Albertans actually live now. The body that does the redrawing is the <em>Electoral Boundaries Commission</em> — an independent commission with judges, lawyers, and public members, not politicians.`,p3:`This is the standard process. This time, the standard process produced something unusual. The commission's five members split 3–2 on what the map should look like, and rather than settling on one recommendation they produced two: a <em>majority proposal</em> (backed by three commissioners) and a <em>minority proposal</em> (backed by two). Both are sitting on the table. A separate committee of MLAs chaired by Brandon Lunty — appointed by the Premier for this specific decision — is choosing between them. The legislature must approve whichever one survives the committee before November 2026.`,p4:`Why it matters to you: the lines decide who your MLA is. They decide which neighbourhoods, towns, and concerns get represented together. If your city is split across four MLAs instead of one, no single representative is accountable for the city as a whole. If your community of interest — a small town, a rural region, a downtown core — is divided between districts, your voice on provincial decisions is diluted. The map also shapes which party can form a government, and at what margins. The audit's specific finding (the minority proposal sits at a structural extreme) is the reason you are reading this site, but the broader question is older and applies to every redistricting cycle: do the lines reflect the way Albertans live, or do they shape the politics following?`,p5:`The rest of this page walks through what the two proposed maps actually do.`,key_terms_lead:`Key terms in this section — click to read:`},editorial_reflect:{heading:`Interlude: What this means for you and your community`,intro_p1:`Set aside, for a moment, the question of which party gains or loses seats. Politicians and parties tend to frame this as a fight over power concentration in the legislature, and at the legislative scale it is. But power concentration in the legislature is not where you experience these maps. You experience them through three concrete questions about your own district:`,intro_q1:`Where does your MLA live?`,intro_q2:`Are they invested in your community?`,intro_q3:`Will the demands of the head dominate the demands of the tails?`,intro_p2:`Every other framing — partisan advantage, supermajority threshold, statistical extreme — eventually points back to those three. The five rungs below walk through how each proposed map answers them, at five scales.`,you_h:`You.`,you_p:`Your electoral district decides who represents you in the legislature. Right now you live in one of 87 districts. Under both proposed maps you may live in a different one — possibly with a different MLA, possibly anchored to different neighbouring communities. If you don't know what district you're in right now, or who your MLA is, you're not alone: most Albertans couldn't name their MLA. But the boundary lines are not abstract. They decide whose phone number is on your local representative's office wall, whose neighbourhood petition gets your name attached to it, whose concerns your MLA hears about first. The postal-code lookup on this site shows which district you sit in under each proposal. If your district changes, your representative changes — and your representative's relationship to your community changes with it.`,community_h:`Your community.`,community_p:`Communities are not abstract either. A high school's catchment area, a chamber of commerce, a faith community, a neighbourhood association — these are real groupings of people with shared local concerns. When a boundary line cuts through them, no single MLA is responsible for the whole. Take Airdrie under the minority proposal: a city of roughly 85,800 people sliced into four electoral districts, each anchored to a different rural hinterland. No single representative is accountable for Airdrie as a city. The same dynamic plays out anywhere a town, neighbourhood, or recognised community of interest is split — the bigger the split, the weaker the representation. The audit measures <em>municipal anchoring</em> (what fraction of each district's perimeter follows existing municipal lines), and the minority proposal scores notably lower than the majority on the anchoring test.`,municipality_h:`Your municipality.`,municipality_p:`When a city is fractured across many representatives, its ability to bargain on provincial decisions weakens. A council asking for transit funding, a school board negotiating a new school, a mayor lobbying for highway extensions — each of those goes better when the city can point to a few MLAs who owe accountability to the city as a whole. The minority proposal splits Calgary's northwest quadrant across multiple districts whose vote-share patterns suggest <em>packing</em> (concentrating one party's voters into a few high-margin seats) on top of <em>cracking</em> (splitting the other party's voters across many low-margin seats). Whether the pattern is intentional is a question the audit cannot answer — boundary geometry doesn't reveal intent. What it can say is that the four statistical measures flag the same districts the structural tests flag, and that the alternative proposal does not produce the same fingerprint.`,region_h:`Your region.`,region_p1:`If you live outside Alberta's cities you have probably noticed political conversations about boundaries always seem to centre the cities. It's a fair complaint, so let's be direct about what this audit does and does not say about rural Alberta.`,region_p2:`What it does <strong>not</strong> say: rural Alberta has too many seats. The EBCA allows district populations to vary by up to 25% so one rural MLA isn't representing a geography the size of southern France. Canadian courts treat the variance as legitimate. Both proposed maps preserve it. Nothing in this audit changes it.`,region_p3:`What it <strong>does</strong> say: in several places on the minority proposal, rural communities are being attached as the <em>tail</em> of a district whose population centre sits in a city. Look at how the minority proposal handles Airdrie — a city of about 85,800 sliced into four districts, each one extended out into a different stretch of rural countryside. The population centre of each new district is the urban slice, not the rural tail. An MLA elected from that kind of district is most likely to live, campaign, and prioritise where the votes are — which means rural communities formerly represented by a dedicated rural MLA become the back half of an urban-led seat. That pattern repeats on the minority proposal in ways it does not on the majority proposal.`,region_p4:`The audit doesn't propose taking seats away from rural Alberta. It asks whether the lines respect the rural communities those seats are meant to represent, or whether rural geography is being used as ballast to absorb urban votes into districts whose centre is somewhere else. If you live in one of those rural tails, the question of which map gets enacted decides whether your MLA represents the rural community you actually live in, or an urban district whose lines happen to include your land.`,province_h:`Your province.`,province_p:`The legislature is what you get when you sum every district's answers to the three questions above. If most districts are anchored to communities whose MLAs actually live in them, the legislature represents those communities. If most districts have rural tails attached to urban heads, the legislature represents the heads — and the tails get whatever attention is left over. The partisan question — which party wins a majority — is downstream of that. The supermajority question — whether one party crosses 58 of 87 seats and unlocks procedural shortcuts like waiving notice periods or accelerating bills through multiple stages in a single day — is downstream of <em>that</em>. At a hypothetical 50/50 provincial split, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. Whether that imbalance pushes a party past 58 seats at the vote shares Albertans actually deliver is a question this audit has not yet directly tested; the opening questions at the top of this page are honest about that gap. Whether the answer to any of these questions matters enough to act on is, again, a question for you.`},editorial_history:{heading:`Context: A short history of gerrymandering`,p1:`The word comes from 1812. Massachusetts governor Elbridge Gerry signed off on a state-senate map whose districts were so contorted in his party's favour that a Boston cartoonist drew one of them as a salamander — wings, claws, a forked tongue. The cartoonist's pun, <em>Gerry-mander</em>, stuck. The shape stuck too: two centuries later, the word still means drawing electoral lines to engineer a partisan outcome.`,p2:`The term endures because the problem endures. Anywhere voters choose representatives from geographic districts, someone has to draw the lines, and the lines can be drawn many ways. Different countries have arrived at different answers about who should do the drawing and what should constrain them.`,p3:`<strong>The United States</strong> treats partisan gerrymandering as a problem the federal courts mostly cannot fix. In <em>Rucho v. Common Cause</em> (2019), the U.S. Supreme Court ruled that partisan gerrymanders are "political questions" outside its jurisdiction. Some states (California, Michigan) have responded by creating independent citizen commissions to draw their own lines; others (Texas, North Carolina) have continued to draw openly partisan maps and defended them on the basis that <em>Rucho</em> permits it.`,p4:`<strong>The United Kingdom</strong> uses four permanent Boundary Commissions — one each for England, Scotland, Wales, and Northern Ireland — staffed by judges and senior civil servants. They redraw lines roughly every eight years against fixed rules (population equality, geographic coherence, respect for local government boundaries). Parliament can in theory reject the commissions' recommendations, but in practice virtually never does; by convention, the commissions' judgment stands.`,p5:`<strong>Australia</strong> delegates the work to the Australian Electoral Commission, a federal independent agency with full authority over both election administration and boundaries. Redistributions happen automatically when a state's seat count changes or seven years pass since the last one. The commissioners' decisions are reviewable on procedural grounds but not on partisan ones. As in the U.K., gerrymandering as Americans know it is virtually unheard of.`,p6:`These three cases bracket the spectrum: courts staying out (U.S.), independent commissions with strong parliamentary deference (U.K.), and a permanent independent agency with full authority (Australia). Canada sits somewhere different again — which is what the next section takes up.`},glossary:{more_link:`Learn more →`,"electoral-district":{term:`Electoral district (ED)`,definition:`The geographic area that elects one member to the provincial legislature. Often shortened to "ED" after first use. Each ED has one MLA. (The word "riding" usually refers to federal districts; in the provincial context the proper term is electoral district.)`},riding:{term:`Riding`,definition:`In Canadian usage, this most often refers to a federal electoral district. The Alberta provincial equivalent is called an "electoral district" (ED). The audit uses the provincial term throughout.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly — the person elected from one electoral district to represent it in the Alberta legislature.`},ucp:{term:`UCP`,definition:`United Conservative Party — Alberta's current governing provincial party. Formed in 2017 from the merger of the Progressive Conservatives and the Wildrose Party; has held government since 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party (Alberta NDP) — Alberta's current official opposition. The Alberta NDP held government from 2015 to 2019.`},gerrymander:{term:`Gerrymander`,definition:`A map drawn so one political party wins more seats than its share of the vote would suggest. The word comes from an 1812 Massachusetts district shaped like a salamander. It is not a legal term in Canada, but the concept is widely studied.`},cracking:{term:`Cracking`,definition:`A gerrymandering technique that splits a voting bloc across many districts so it never reaches a majority in any single one. For example, dividing a city across four ridings so its voters are outnumbered in each.`},packing:{term:`Packing`,definition:`A gerrymandering technique that concentrates one party's voters into a small number of districts. The party wins those districts overwhelmingly but "wastes" many votes — leaving fewer of its voters available to compete in other districts.`},draining:{term:`Draining`,definition:`A term this audit uses for a follow-on effect of cracking and packing: the wasted votes those techniques produce get pushed into strategically chosen places, altering the political character of nearby electoral districts. It is the audit's own framing rather than an established concept in the redistricting literature — the audit tests for the effect and finds results consistent with it, but treats it as exploratory rather than a settled methodology.`},anchoring:{term:`Anchoring`,definition:`How firmly the proposed boundaries follow existing municipal lines (city limits, town boundaries). A highly anchored map mostly respects those lines; a loosely anchored map departs from them often — especially at politically meaningful spots, which is a structural warning sign.`},"charter-s3":{term:`Section 3 of the Charter`,definition:`The section of the Canadian Charter of Rights and Freedoms that guarantees citizens the right to vote. Canadian courts have interpreted it not as a strict "one person, one vote" rule but as a right to "effective representation."`},"effective-representation":{term:`Effective representation`,definition:`The standard Canadian courts apply when judging electoral boundaries. It means voters should have a meaningful voice — not just numerical equality of riding populations, but also recognition of community ties, geography, and minority representation. The leading statement is from the Supreme Court of Canada's 1991 Saskatchewan Reference.`},ebc:{term:`Electoral Boundaries Commission (EBC)`,definition:`The body that draws Alberta's provincial electoral boundaries under the EBCA. The 2026 commission was chaired by Justice Miller and split 3–2 among its commissioners, producing two competing proposals (the majority and minority proposals) rather than a single recommendation.`},"lunty-committee":{term:`Lunty committee`,definition:`An MLA committee chaired by Brandon Lunty — an MLA appointed by the Premier — choosing between the EBC's majority and minority proposals before the November 2026 deadline. The committee is separate from the EBC; the legislature created it for this specific decision and it is not part of the standard EBCA process.`},ebca:{term:`EBCA`,definition:`The Alberta Electoral Boundaries Commission Act — the law that governs how electoral boundaries are drawn in the province. It sets up the commission, the public-hearing process, and the rules for when a new map takes effect.`},fsa:{term:`Forward sortation area (FSA)`,definition:`The first three characters of a Canadian postal code (the letter-digit-letter part). About 270 FSAs cover Alberta. Most fall entirely within a single electoral district.`}},body:{section_link_aria:`Link to section`,the_map:{heading:`1: The Map`,p1:`The cover map is the best single image in this audit. Here is how to read it.`,p2:`Alberta is divided into 4,765 Voting Areas — small geographic zones Elections Alberta uses to count polling-station ballots. Each one is coloured by how people in it actually voted in 2023: orange where NDP votes are concentrated, blue where UCP votes are concentrated. But the colour only becomes dark and saturated where a lot of people live. A Voting Area that covers hundreds of square kilometres of parkland or farmland stays pale — nearly invisible. The map lights up where people are, and fades where they aren't.`,p3:`This is very different from the Alberta you see on election night. Most election maps colour entire ridings solid blue or orange based on who won. Rural ridings are geographically large and the UCP wins most of them, so election-night Alberta looks like a wall of blue with small orange pockets in Edmonton and Calgary. The cover map uses the same votes and the same geography — but shows them weighted by where people actually live. What appears is a province where most of the population is concentrated in a dense arc of cities, and those cities vote very differently from the rural map that normally represents them.`,p4:`The boundary lines drawn over the colour are the minority commission's 89 proposed electoral districts — the map this audit ends up critiquing. The audit's work is to ask what those lines do to the people underneath them.`,p5:`This image is what makes the stakes plain. A province that looks like it votes one way on a standard map is actually a province where most of the people live in areas that vote the other way. Once the population is visible underneath the boundary choices, those choices stop looking random.`},structural_results:{heading:`Structural audit results — before any statistics:`,body:`The majority map crosses <strong>zero of five</strong> pre-registered structural thresholds. The minority map crosses <strong>four of the five</strong>; the fifth (anchoring) is neutral — both maps fall within the 70–85% Canadian norm. These are geometric measurements — population spread, <button class="vocab-term" data-def="how closely a district's borders follow pre-existing city and municipal limits, rather than cutting through them" aria-expanded="false">municipal anchoring</button>, Airdrie split count, NW Calgary population excess, and chair-flagged boundary anomalies — requiring no election data and no statistical sampler. The next section tests both maps against 1,010,000 computer-generated neutral maps and reaches the same conclusion through a completely different instrument.`},clean:{heading:`6: When a fair-looking map isn't`,legal_label:`A NOTE ON LEGAL TERMINOLOGY`,legal_body:`"Gerrymandering" has no legal definition in Canadian law. The word is used throughout this report in its everyday political sense — manipulating electoral boundaries for partisan advantage. The legal tests actually applying in Canada are different: whether boundaries provide "effective representation" under s.3 of the <em>Charter of Rights and Freedoms</em> (the constitutional standard the Supreme Court of Canada set in the 1991 <em>Saskatchewan Reference</em>), and whether the commission followed the rules of Alberta's <em>Electoral Boundaries Commission Act</em>. The audit's findings are evidence bearing on those legal questions. They are not proof of a legally-defined wrong, and this report does not describe them in those terms.`,intro_p1:`The cleanest single question to ask of any electoral map is this: if the province's vote split exactly evenly between the two main parties, what seat count would the map produce? This holds the electorate constant and asks the map alone what it does.`,intro_p2:`To answer this, the audit generated 1,010,000 computer-simulated, mathematically neutral Alberta maps. The simulation used the official Elections Alberta shapefiles and held to the exact same statutory rules and geographic boundaries the commission used. The commission's two 2026 maps were then placed into that distribution to see how normal they are. The simulation ran four independent chains of 252,500 steps each, with the base seed drawn from the Cloudflare drand beacon and pre-registered at OSF before execution.`,howmcmc_label:`HOW THE SIMULATION WORKS`,howmcmc_mcmc:`<strong>MCMC (Markov Chain Monte Carlo)</strong> is a method for exploring a large space — here, the space of all legal Alberta maps — by taking random steps from a starting point. Each step proposes a small swap between adjacent districts; if the result stays within the statutory rules, it becomes the new starting point. After enough steps, the visited maps form a representative sample of legal plans. The simulation is seeded from the Cloudflare drand public randomness beacon to prevent any cherry-picking of starting conditions.`,howmcmc_recom:`<strong>ReCom (Redistricting Compiler)</strong> is the specific algorithm used here. Each step merges two adjacent districts into one region and re-splits it randomly into two new valid districts, preserving contiguity and population balance by construction — so the algorithm never needs to reject an invalid proposal.`,prereg_label:`PRE-REGISTRATION`,prereg_body:`Pre-registration means writing down the exact tests, thresholds, and predicted directions before looking at any data, and locking those commitments into a public time-stamped record. The Open Science Framework (OSF) is the public repository where this audit's commitments are filed. It prevents retrofitting: if a result doesn't emerge cleanly, the threshold cannot be changed after the fact and then presented as always having been the test. All five structural tests and four partisan-fairness metrics in this audit were registered at OSF before any simulation was run.`,neutral_p:`In Alberta, the neutral answer is not 50/50. <em>Across 1,010,000 computer-simulated legal Alberta maps, the median map gives the UCP only 44.8% of the seats at 50/50 votes</em> — a typical Alberta map under neutral votes hands the NDP a small seat majority. This is counterintuitive but mechanical: rural UCP voters win their ridings by 60-40 margins (wasting many "extra" UCP votes), while urban NDP voters win their ridings by tighter 51-49 margins (wasting fewer NDP votes per win). At neutrality, NDP comes out ahead on seat efficiency.`,full_dist:`The full distribution from the canonical 1,010,000-map simulation:`,t1_col_a:`Where the map sits`,t1_col_b:`UCP seats at 50/50 votes`,t1_r1_a:`Median Alberta map`,t1_r1_b:`44.8% — NDP slight seat majority`,t1_r2_a:`95th-percentile map`,t1_r2_b:`47.1%`,t1_r3_a:`99th-percentile map`,t1_r3_b:`48.4%`,t1_r4_a:`<strong>Maximum across 1,010,000 maps</strong>`,t1_r4_b:`<strong>below 51.7% (fewer than 100 plans reach this value)</strong>`,seat_count_note:`A note on seat counts. The 2026 commission maps each have <strong>89</strong> districts; the audit's computer simulation runs on the <strong>87</strong>-district 2019 map (its starting substrate); the November Lunty committee will produce <strong>91</strong>. All percentages are seat <em>shares</em>, comparable across these denominators. The simulation uses the 2019 map as its starting point because the ReCom algorithm needs a legally enacted map to propose swaps from — the 2019 map is the last enacted Alberta electoral map. Using either commission proposal as the substrate would be circular: we would be measuring whether a map is extreme compared to maps derived from itself.`,pattern_intro:`The results — placing the three real maps in this distribution — point to a specific, surgical pattern of boundary drawing.`,sub1_h:`All four statistical measures fire simultaneously`,sub1_p:`When the official Elections Alberta shapefiles are used, the minority map is a statistical outlier on every partisan-fairness metric — not just the tipping-point one.`,t2_col_a:`Map`,t2_col_b:`Efficiency gap`,t2_col_c:`Mean-median`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Declination measures the angular difference between the seats-votes curve for each party. Negative values favour the UCP; positive favour the NDP.">Declination</a>`,t2_col_e:`Seats at 50/50`,t2_r1_a:`Majority 2026`,t2_r1_b:`+0.04% (p15.5)`,t2_r1_c:`−3.6% (p2)`,t2_r1_d:`+0.027 (p81)`,t2_r1_e:`46.1% (p83)`,t2_r2_a:`Minority 2026`,t2_r2_b:`<strong>+3.96% (p94.4)</strong>`,t2_r2_c:`<strong>+1.0% (p99.98)</strong>`,t2_r2_d:`<strong>−0.077 (p1.2)</strong>`,t2_r2_e:`<strong>51.7% (p99.99)</strong>`,sub1_close:`The majority map sits comfortably inside the normal range on three of four metrics. Its mean-median sits at p2 in the NDP-favourable direction — an unusual result but pointing the wrong way to help the UCP. The majority map's close adherence to municipal boundaries places NDP-heavy urban cores into their own compact districts, where NDP votes win by efficient margins while UCP rural wins tend to be by larger margins; this mild structural NDP efficiency advantage is what shows up in the mean-median measure. The minority map is in the tail on all four, each pointing in the same partisan direction.`,sub2_h:`The 50/50 tipping point: fewer than 100 of 1,010,000 neutral maps reach it`,sub2_p:`The tipping-point metric introduced above — UCP seats at a 50/50 provincial vote — is the most intuitive way to compare the three maps.`,t3_col_a:`Map`,t3_col_b:`UCP seats at 50/50 votes`,t3_col_c:`Where it sits`,t3_r1_a:`2019 enacted`,t3_r1_b:`46.0%`,t3_r1_c:`83rd percentile — inside the normal range`,t3_r2_a:`<strong>Majority 2026</strong>`,t3_r2_b:`<strong>46.1%</strong>`,t3_r2_c:`<strong>83rd percentile — well within bounds</strong>`,t3_r3_a:`<strong>Minority 2026</strong>`,t3_r3_b:`<strong>51.7% (46 seats)</strong>`,t3_r3_c:`<strong>99.99th percentile — fewer than 100 of 1,010,000 neutral draws reach this</strong>`,sub2_close:`Fewer than 100 of 1,010,000 computer-simulated neutral Alberta maps produced a <code>seats@50/50</code> value as high as the minority proposal's. Based on actual recent voting patterns, it would award the UCP 60 seats (compared to 55 in the majority proposal). The majority proposal is the kind of map a neutral procedure routinely generates. The minority proposal is the kind of map you have to specifically aim to draw.`,sub3_h:`What this means in plain language`,sub3_p:`The official shapefiles reveal a map statistically extreme in the same partisan direction on all four measures at once. The joint probability of a neutral drawing process producing a map this extreme across all four measures simultaneously is roughly one in 15 million (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>, <a href="https://osf.io/6pt83" rel="noopener">pre-registered Fisher combined test</a>). This is not a rounding error or a measurement artefact — it is the same answer from four independent statistical instruments read in the same room.`,details_summary:`What this p-value means — and what it doesn't`,details_p1:`A p-value answers one question: if the map were drawn by a neutral process, how often would we see a result this extreme or more extreme? At p&nbsp;=&nbsp;6.87×10<sup>−8</sup>, the answer is about once in 14.5 million trials.`,details_p2:`This is a frequentist hypothesis test, not a measurement of intent. It does not say the commission intended to gerrymander, and it does not quantify how unfair the map is in practical terms. It says the boundary pattern is statistically inconsistent with a neutral drawing process — the same conclusion a randomized audit would reach regardless of who drew the map or why.`,details_p3:`The test was pre-registered before the data were analyzed (<a href="https://osf.io/w2s8k" rel="noopener">OSF registration w2s8k</a>). The pre-registration specifies the null hypothesis, the metrics, and the rejection threshold in advance, so the result cannot be attributed to choosing a favorable framing after seeing the numbers.`,szat_label:`SWING-ZONE ALLOCATION TEST (SZAT)`,szat_body:`SZAT is the audit's second independent test, and it asks a different question from the simulation: not "is this map extreme overall?" but "are the specific line choices partisan-neutral?" It works by isolating only the Voting Areas where the minority's map differs from the majority's — the contested re-draws — and testing whether those particular choices, taken together, shift vote efficiency in one party's direction. Because it compares only the points of departure, it automatically controls for everything the two maps share: the same geography, population targets, and statutory rules. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Technical details and bootstrap results →</a>`,two_q:`<strong>Two questions, one answer.</strong> The 1,010,000-map simulation asks: <em>is this map extreme compared to neutral maps drawn on the same Alberta geography?</em> A second, separate test — called the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Swing-Zone Allocation Test</a> — asks a different question: <em>are the specific lines on the map partisan-neutral?</em> It works by looking only at the Voting Areas where the minority drew differently from the majority and asking whether those particular choices, taken together, shifted vote efficiency in one party's direction. Because it compares only the places where the two maps differ, it automatically controls for everything they share — the same provincial geography, the same population targets, the same statutory rules. Both questions return the same answer. This is why the one-in-15-million figure is a combined result rather than a single test: it is two independent lines of evidence converging.`,super_lead:`This explains why the minority proposal had to be such an extreme statistical outlier (p99.99) against 1,010,000 neutral simulations. In an 89-seat legislature, a two-thirds supermajority requires exactly 60 seats. Neutral procedures do not produce 60-seat outcomes on Alberta's geography at neutral votes; reaching the threshold requires deliberate boundary choices departing from the neutral baseline.`,super_label:`WHY A SUPERMAJORITY MATTERS`,super_body:`Under Canada's Westminster parliamentary system, a simple majority (45 seats) is enough to pass routine laws and budgets. A two-thirds supermajority (60 seats) does more. It lets the governing party invoke "closure" to shut down debate, rewrite procedural rules without opposition consent, and control the composition of every legislative committee. It also insulates the government from internal dissent: even with half a dozen backbenchers crossing the floor, the government still holds a working majority. A simple majority lets you drive the car; a 60-seat supermajority lets you rewrite the traffic laws.`,super_close:`By strategically diluting urban voters into surrounding rural-edge districts (the "urban hybridization" pattern identified in Lane 2), the minority proposal engineers the exact structural firewall needed to secure those 60 seats. The Lane 2 structural finding and the Lane 1 statistical finding converge on the same proposal, the same direction, and the same communities.`,sub4_h:`Confirmation from the targeted-procedure test`,sub4_p:`To be sure this isn't a quirk of the neutral simulation's known compactness preference, the audit ran a targeted hill-climbing procedure (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et al. 2022 — cited and described in the technical report</a>) in both directions: maximising UCP seats and maximising NDP seats. Same number of steps (40,000) in each direction, same statutory constraints, same provincial geometry.`,t4_col_a:`Procedure`,t4_col_b:`Most-extreme value reached`,t4_col_c:`What it tells us`,t4_r1_a:`Neutral MCMC, max produced`,t4_r1_b:`below 51.7% UCP seats @ 50/50`,t4_r1_c:`The natural ceiling under neutral drawing`,t4_r2_a:`Neutral MCMC, min produced`,t4_r2_b:`~39% UCP seats @ 50/50`,t4_r2_c:`The natural floor under neutral drawing`,t4_r3_a:`Targeted hill-climb, UCP-maximizing`,t4_r3_b:`<strong>52.9%</strong>`,t4_r3_c:`What a procedure deliberately aiming for UCP advantage can reach`,t4_r4_a:`Targeted hill-climb, NDP-maximizing`,t4_r4_b:`<strong>37.9%</strong>`,t4_r4_c:`What a procedure deliberately aiming for NDP advantage can reach (below the neutral floor)`,sub4_close:`The minority map's 51.7% sits closer to the targeted-UCP ceiling (52.9%) than to the neutral median (44.8%). The majority map's 46.1% sits at the neutral median. Both the 2019 enacted map and the 2026 majority fall comfortably within what neutral procedure routinely produces — different vote shares, same zone of unremarkable outcomes. The majority continues 2019 Alberta practice on the partisan-fairness axis the same way it continues 2019 practice on municipal anchoring (80.0% vs 2019's 75.2%). Two maps drawn under the same Alberta rules, by the same five commissioners, in the same room: one lands where neutral procedures routinely produce, the other lands where you have to specifically aim to land.`,sub4_quote:`<em>This</em> is the shape of the finding, and it is also the framing a court would actually apply.`,sub5_h:`Ruling Out Alternative Explanations`,sub5_p:`When presented with a statistical outlier of this magnitude, a rigorous audit must rule out innocent explanations before attributing these patterns to deliberate design. The structural data (Lane 2) systematically dismantles the standard alternative defenses:`,defense1:`<strong>The "Natural Political Geography" Defense:</strong> <em>("Urban voters are naturally packed; the map just reflects Alberta's geography.")</em> The 1,010,000 simulations already account for Alberta's natural geography. The simulation proves: while geography gives the UCP a baseline efficiency advantage, it naturally caps around the 83rd to 90th percentile. The minority map sits at the 99.99th percentile — an extreme outlier <em>even when compared to Alberta's naturally skewed baseline</em>.`,defense2:`<strong>The "Communities of Interest" Defense:</strong> <em>("The odd shapes were drawn to keep specific communities together.")</em> If you are trying to keep communities together, you follow municipal borders. The majority map followed existing city limits 80% of the time. The minority map followed them 72% of the time — both within the 70–85% Canadian norm. What the minority map does do is actively split the unified city of Airdrie into four separate pieces, and place three of its boundary decisions precisely in the urban-edge zones the commission chair flagged as geometrically anomalous — choices not explainable by community-of-interest logic.`,defense3:`<strong>The "Population Equality" Defense:</strong> <em>("They had to draw weird boundaries to make sure every district had the exact same population.")</em> The minority map is actually much <em>worse</em> at population equality. Its Population Mean Absolute Deviation (MAD) was 4,707 — 48% wider than the majority map's 3,180 — placing it at the 99th percentile of the canonical ensemble (only 1 in 100 neutral maps produces a worse spread). It sacrificed population equality to achieve its shape.`,defense4:`<strong>The "Incompetence or Bad Luck" Defense:</strong> <em>("They just drew a sloppy map and got unlucky with the numbers.")</em> Hitting exactly 60 seats for a supermajority while also splitting Airdrie into four pieces and placing three boundaries in the exact zones the commission's own chair flagged as anomalous requires surgical precision. The joint probability of accidentally drawing a map hitting the extreme statistical tail across four independent partisan metrics simultaneously is roughly <strong>1 in 15 million</strong> (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>). You cannot blunder your way into the 99.99th percentile.`,sub5_close:`What the data shows is that the minority proposal worsened both population parity and community coherence relative to what the same five commissioners produced simultaneously under identical statutory rules. The audit does not determine what the minority commissioners intended — boundary geometry cannot reveal intent — but the structural departure from both the neutral ensemble and the majority proposal's output stands regardless of intention.`,sub6_h:`A note on the R cross-validation`,sub6_p1:`An earlier version of this audit (using approximated rather than official shapefiles) cross-validated the Python ReCom ensemble against the R <code>redist</code> package's Sequential Monte Carlo sampler. The cross-check produced unstable results: across three runs with the same nominal seed, the fraction of plans reaching the old minority value (48.3% on the approximated geometry) was 5.6%, then 28%, then 58% — a sampler-convergence failure, not a discovery. The full write-up is at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`With official Elections Alberta shapefiles, the minority map's <code>seats@50/50</code> rises to 51.7% — a value fewer than 100 of 1,010,000 neutral plans reach. The R cross-validation question becomes moot: zero plans from either sampler reach the canonical value at comparable sample sizes.`,sub6_asymm:`<strong>The asymmetry around 50/50 is more telling than the inversion itself.</strong> A precision sweep of the seat-vote curve at 0.01-percentage-point resolution finds the minority map keeps the UCP at or above the 45-seat legislative-majority threshold down to a UCP provincial vote share of about <strong>49.7%</strong>. This is technically a vote-seat inversion — the UCP would form government on the minority map while losing the popular vote by 0.3 percentage points — but 0.3 points is well within ordinary polling noise, so on its own this is not a dramatic finding. What <em>is</em> dramatic is the contrast: on the <strong>majority</strong> map, the UCP would need to <em>win</em> the popular vote by about 4 percentage points to reach the same 45-seat threshold. Both maps face the same Alberta geography and the same statutory rules; the gap between them — 0.3pp vs +4pp — is structural difference, not noise.`,sub6_close:`This is the structural-bias finding the audit holds with confidence. It is geometry-only; it does not depend on any election result; it does not move when polls do.`,sub6_caveat:`<strong>One caveat the audit takes seriously.</strong> A real electorate is not a uniform 50/50. Voters can swamp any map's structural lean with enough swing — a particularly upset or inspired electorate will tip the result regardless of how the boundaries are drawn. The 50/50 test isolates <em>the map's contribution to the outcome</em>, not the outcome itself. What it shows is what the map does when the electorate doesn't decide for it.`,sub7_h:`The bottom line`,sub7_p1:`The audit's central finding is geometric. <strong>Lane 2 — the structural-irregularity scorecard — is the foundation; Lane 1 is the proof that the geometry is doing partisan work.</strong>`,sub7_p2:`The chart below puts both lanes on a single picture. The horizontal axis is Lane 1 (the partisan-fairness efficiency gap, where further right means more UCP-favoured); the vertical axis is Lane 2 (the count of structural-fairness tests the proposal fails, out of five, where higher means more structural problems).`,stakes_fig_alt:`Scatter plot with efficiency gap on the horizontal axis and count of structural tests failed on the vertical axis. The 2019 enacted map and the majority 2026 map cluster in the safe lower-left corner. The minority 2026 map appears in the upper-right outlier region.`,stakes_fig_caption:`The two ways of measuring the two commission proposals, plotted together. Left-to-right: how skewed the proposal looks on the partisan-fairness number — the further right, the more it favours the UCP. Bottom-to-top: how many of five structural-fairness tests the proposal fails — the higher, the worse. The 2019 enacted map sits in the safe corner: low on both. The majority 2026 proposal stays flat at zero structural problems and near-zero partisan skew (+0.1%). The minority 2026 proposal is a structural outlier on every test that distinguishes the two maps (4 of 5; the fifth, anchoring, is neutral for both); its efficiency gap (+4.0%) sits just below the Alberta threshold line.`,stakes_table_intro:`The same findings in plain summary form, leading with the structural finding because the cross-validated evidence supports it most strongly:`,t5_col_b:`Lane 2: Structure (geometry-only, no votes)`,t5_col_c:`Lane 1: Numbers (vote-dependent)`,t5_r1_a:`<strong>Majority 2026</strong>`,t5_r1_b:`clean — crosses <em>no</em> structural threshold`,t5_r1_c:`inside the normal range on every metric (<code>seats@50/50</code> 46.1% — p83; efficiency gap +0.04%)`,t5_r2_a:`<strong>Minority 2026</strong>`,t5_r2_b:`<strong>crosses 4 of 5 structural thresholds</strong> by a wide margin (anchoring neutral — both maps within Canadian norm)`,t5_r2_c:`statistical outlier on all four partisan-fairness measures simultaneously — <code>seats@50/50</code> 51.7% (p99.99, fewer than 100 of 1,010,000 reach it); efficiency gap +3.96% (p94.4); all four pre-registered; Fisher combined p&nbsp;=&nbsp;6.87×10<sup>−8</sup>`,details2_summary:`Why Lane 2 carries the case — technical detail`,details2_p:`The audit pre-registered five structural-irregularity tests on April 24, 2026 before the final simulation results were compiled. Anchoring is neutral for both maps; on the remaining four tests the minority crosses every one and the majority crosses none. Those measurements are geometric — they don't depend on any statistical sampler or any vote attribution. Lane 1 (the partisan-fairness numbers) corroborates Lane 2 strongly under canonical official shapefiles: the minority is a statistical outlier on all four pre-registered metrics simultaneously, with a joint neutral-null probability of p&nbsp;=&nbsp;6.87×10<sup>−8</sup> (pre-registered Fisher combined test — a method that combines four independent test results into a single probability by multiplying their individual tail probabilities; the combined figure is far smaller than any single test's because all four point the same direction; OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>). The question of whether Lane 2's unusual geometry is the specific <em>mechanism</em> behind the Lane 1 numbers was tested and the answer is no — see <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>. The Swing-Zone Allocation Test shows the contested boundary choices are partisan-skewed, but the tested question was whether the boundary shapes themselves — the lasso corridor, the park extension — are the direct cause of the seat swing; they are not. The seat effect comes from how redrawn Voting Area assignments shift vote efficiency across districts, not from the shapes per se. Both lanes flag the minority map; they reach it through independent instruments. Lane 2 is the central finding. Lane 1 corroborates without carrying.`},impact:{heading:`5: Effects on Representation`,lanes_label:`LANE 1 AND LANE 2`,lanes_body:`<strong>Lane 1 (numbers)</strong> uses election results to test whether the map converts votes into seats fairly — it asks how the map performs across different vote splits. <strong>Lane 2 (structure)</strong> examines only the drawn lines — city splits, population spread, boundary shapes — with no election data at all. Each lane is independent: a map can fail one while passing the other. The minority proposal fails both; the majority passes both.`,intro:`Lane 1 depends on which election results you score the maps against. Lane 2 does not. The structural evidence is in the maps themselves — drawn lines, split cities, where the boundaries do and don't follow administrative lines that exist for other reasons. On these tests, the two maps are not close.`,fig_alt:`Bar chart comparing five structural-fairness tests side by side. The majority map bars sit at zero or well inside safe ranges. The minority map bars cross the threshold on four of the five tests by a wide margin; the fifth (anchoring) is neutral for both maps.`,fig_caption:`The five structural-fairness tests, side by side. Teal bars are the majority map; purple bars are the minority map. The dashed line in each row marks the failing threshold. The minority bars cross the threshold on four of the five tests by a wide margin; the fifth (anchoring) is neutral for both maps. The majority bars sit flat at zero or well inside the safe range.`,table_intro:`The same five tests in tabular form, with each test's threshold stated alongside the result. The bottom row is the audit's <em>summary</em> — the count of tests each map fails out of the five.`,table_col_test:`Test`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Border follows existing municipal lines (70–85% Canadian norm)`,table_r1_b:`80% — within norm`,table_r1_c:`72% — within norm`,table_r1_d:`N/A — both within Canadian norm`,table_r2_a:`Population spread (tighter is better)`,table_r2_b:`3,180`,table_r2_c:`4,707 — 48% wider`,table_r2_d:`Structural (Reduces vote equality)`,table_r3_a:`NW Calgary population excess above average`,table_r3_b:`2.8%`,table_r3_c:`11.5%`,table_r3_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r4_a:`Boundaries flagged by the commission's own chair`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`N/A`,table_r5_a:`Airdrie split (constraint minimum: 2)`,table_r5_b:`2 pieces`,table_r5_c:`4 pieces`,table_r5_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r6_a:`<strong>Pre-registered summary</strong> (&ge; 4 of 5 = outlier)`,table_r6_b:`<strong>0 of 5 fired</strong>`,table_r6_c:`<strong>4 of 5 fired</strong> (anchoring test neutral — both maps within Canadian norm; remaining 4 tests all fire)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`A separate finding, applied only to the minority: <strong>five of six of the minority commissioners' published rationales fail under independent check</strong>. The test runs against the minority only because the majority did not publish a contested-redraw rationale list — the audit cannot apply it symmetrically, and it is reported here as a single flag rather than as additional rows in the structural-irregularity count. (A seventh redraw the audit had previously listed turned out to rest on a federal-boundary claim untraceable in the minority report; it has been removed rather than left as a weak claim.)`,chair_appendix_p:`The audit also tested the chair's separate, blanket assertion in Appendix C that the minority's seven contested hybrid configurations had <strong>no public support</strong> in the 1,140+ public submissions. A keyword search across the full submission archive (94% machine-parsed, 6% image-only and excluded; methodology and per-configuration evidence at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) returned a more nuanced picture than either the chair's blanket claim or its blanket dismissal: the chair was right on three of seven (Airdrie 4-way split, Calgary–Nolan-Hill–Cochrane hybrid, and the St. Albert minority alternative each lack any documented support), wrong on three of seven (Rocky Mountain House–Banff Park drew an explicit, detailed proposal from at least one Clearwater-area submission plus several aligned ones; Olds–Three-Hills–Didsbury was supported by Beiseker residents in writing; Chestermere drew multiple submissions opposing a Calgary merger that materially align with the minority's intent), and partially wrong on one (Red Deer hybrids drew a peri-Red-Deer hybrid proposal from a sitting Red Deer councillor, with directional but not configuration-exact alignment). The chair's Appendix C "no public support" sweep is therefore demonstrably overbroad — three of seven are demonstrably false — but it is not invented out of whole cloth, since three of seven do hold up. <strong>This finding cuts against the chair, not against the minority.</strong>`,summary_p:`<strong>On Lane 2, the majority crosses zero structural thresholds. The minority crosses every one of them by a wide margin.</strong>`},cpd:{heading:`4: Cracking, Packing, and Draining`,vocab_label:`Three moves, one playbook`,vocab_packing:`<strong>Packing</strong> means cramming one party's voters into districts the party wins by landslides — each packed ballot still counts, but it contributes nothing beyond victory. Large, lopsided wins. Wasted votes.`,vocab_cracking:`<strong>Cracking</strong> means splitting a community across multiple districts so it wins none of them outright. A city strong enough to carry two seats gets carved into four, each tethered to a different rural area. Diluted votes. No seat for anyone.`,vocab_draining:`<strong>Draining</strong> is the spatial companion: packed and cracked districts are placed next to each other so over-concentrated supporters on one side "drain" voting power away from the contested districts nearby. The adjacency pattern amplifies both effects — packing and cracking reinforce each other across district lines.`,vocab_disclaimer:`All three can occur without any explicit partisan intent. What the audit measures is whether the pattern — and its statistical magnitude — is consistent with what a neutral map-drawing process produces. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Full methodology at §5 of the technical report.</a>`,fig_alt:`Map showing the division of Airdrie into four separate districts under the minority map`,fig_caption:`The division of Airdrie into four separate districts under the minority map, diluting its urban voting power.`,intro:`The five commissioners worked from the same statutory rules, the same provincial geography, the same archive of 1,140 public submissions, and the same demographic data. Their two competing drafts agree on most of Alberta. Where the drafts diverge, they diverge on choices someone in the room had to make. Three of those choices are worth seeing as choices, not numbers.`,airdrie_p:`<strong>It splits the City of Airdrie into four pieces.</strong> The law caps each electoral division at one-and-a-quarter times the provincial average, so Airdrie needs at least two divisions. The majority map gives it two. The minority gives it four — north to Calgary-Nolan Hill-Cochrane, east to Airdrie East, west to Calgary-Foothills-Airdrie West, and centre-south to Calgary-Airdrie — each one stapled to a different rural or Calgary-edge district. An Airdrie resident with a question for her MLA has to know which quarter of the city she lives in before she can call the right office. Her neighbours two blocks over will give her three different answers. The PTA at her child's school cannot send a single delegation to one MLA on a school-funding question; they have to coordinate four delegations to four offices, each MLA primarily accountable to a different rural or suburban constituency. The minor-hockey association, the food bank, the Chamber of Commerce — every organization that operates citywide now operates across four provincial ridings.`,airdrie_callout_label:`WHY AIRDRIE MATTERS`,airdrie_callout_p1:`Airdrie is the largest Alberta city without its own MLA. At 85,805 people (2024 municipal census) it is bigger than Red Deer; it has one council, one tax bill, one school division — every civic system treats it as a unit.`,airdrie_callout_p2:`Splitting it across four provincial divisions — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Calgary-Nolan Hill-Cochrane, and Airdrie East — each primarily identified with a different surrounding jurisdiction, removes Airdrie from the political map at the level of government that draws it. The city has 85,805 residents and zero seats in the legislature where a majority of voters call the place home.`,airdrie_callout_p3:`A four-way split is invisible to every partisan-fairness test except the one that asks: can a voter find their MLA?`,airdrie_callout_summary:`Both maps are legal. The four-way split is a choice.`,airdrie_btn:`Show flagged districts on map`,anchoring_p:`<strong>Where it departs from municipal lines, it departs at strategically important places.</strong> When electoral maps follow the edge of a city or town, voters recognize where their division begins and ends — the property-tax line, the school-division line, the local-election ward line, and the provincial-election line all coincide. Statistics Canada publishes these boundaries for free. On official Elections Alberta shapefiles, both maps follow municipal lines at comparable overall rates: the majority at 80%, the minority at 72%, both within Canada's 70–85% norm (Quebec: 78%, Ontario: 82%, BC: 71%; comparator commissions documented in the monograph). (The audit's initial provisional analysis showed the minority anchoring at only 15%; the figure did not survive recomputation on official shapefiles — see the correction note below.) The striking observation is not the overall rate but where the minority's departures are concentrated: the three boundaries the commission's own chair flagged as anomalous — Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">show ↗</button>'s extension into uninhabited national-park land, the Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">show ↗</button> lasso corridor, and the Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">show ↗</button> reach — are each departures from pre-existing civic geography in the exact urban-edge zones where pairing urban and rural voters most directly affects which party wins the seat.`,anchoring_followup:`The minority commissioners gave reasons for each of the three flagged boundaries. For Rocky Mountain House–Banff Park, they cited geographic size, the Highway 22 corridor, and the proximity of First Nations reserves to Rocky Mountain House; the commission chair called the extension into uninhabited national park land "a bad faith effort" to satisfy the area criterion, and the phrase appears in the commission's official final report. For Nolan Hill–Cochrane, they cited shared transportation and employment ties between northwest Calgary and Cochrane; Statistics Canada journey-to-work data shows only 35.8% of Cochrane workers travel to Calgary at all, with most working within Cochrane itself. For the Olds–North Airdrie reach, they cited Highway 2 corridor continuity; the audit found the specific Airdrie extension fails on population grounds. Independent check found five of the minority's six published sub-rationales fail or only partially hold against primary data.`,packing_p:`<strong>One area of Calgary is carved up to concentrate NDP voters into larger-than-average divisions.</strong> In Calgary's northwest quadrant <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">show ↗</button>, the minority map's divisions average 11.5% above the province-wide population — versus 2.8% on the majority. The same geographic zone, drawn by the same commission under the same constraints, produces districts a quarter larger on one map than on the other. This fits the structural signature of <em>packing</em>: concentrating one party's voters into fewer, larger districts so each of their ballots weighs less. Packing and <em>cracking</em> (splitting a party's voters thinly across districts they narrowly lose) are the two classic gerrymandering moves; both shrink a party's seat count below its vote share.`,chair_p:`The commission chair — appointed under the same Act, working from the same submissions — flagged three boundaries on the minority map as geographically anomalous: Rocky Mountain House–Banff Park's extension into uninhabited national park land; the Calgary-Nolan Hill–Cochrane lasso-shaped corridor; the Olds–Three Hills–Didsbury reach into north Airdrie. The majority received zero such flags from the same chair. (The chair's published criticism covers seven boundary configurations in total — four geometric flags in the main report and three in Appendix C. This audit independently confirmed anomalous geometry for three of the four geometric flags; the fourth, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">show ↗</button>, did not meet the audit's confirmation threshold.)`},litmus:{heading:`3: The 1,010,000-Map Litmus Test`,fig_alt:`Histogram showing the distribution of efficiency gaps across 250,000 neutral Alberta maps. Most maps cluster near zero. The minority commission map (purple line) sits at the 94th percentile (+3.96%), in the shaded right tail. The majority map (teal line) sits at +0.04%, well within the normal range.`,fig_caption:`Distribution of <button class="vocab-term" data-def="a measure of how lopsidedly votes are converted into seats — positive values favour the UCP, negative values favour the NDP" aria-expanded="false">efficiency gaps</button> across 250,000 neutral Alberta maps drawn from the same geography. Most neutral maps cluster near zero; the shaded right tail marks the top 10%. The minority proposal&rsquo;s +3.96% sits at the 94th <button class="vocab-term" data-def="the percentage of maps that scored lower — p94 means 94 out of 100 neutral maps were less partisan than this" aria-expanded="false">percentile</button> — a region fewer than 6 in 100 neutral maps ever reach. The majority proposal&rsquo;s +0.04% is indistinguishable from what a neutral process typically produces.`,table_intro:`The table compares the two maps. The first five rows use no election results — they're properties of the lines themselves. The last two depend on how votes were attributed to each district.`,table_col_measured:`What was measured`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Population spread across districts (tighter is better)`,table_r1_b:`3,180`,table_r1_c:`4,707 — 48% wider`,table_r1_d:`Structural (Reduces vote equality)`,table_r2_a:`NW Calgary population excess above average`,table_r2_b:`2.8%`,table_r2_c:`11.5%`,table_r2_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r3_a:`Airdrie split`,table_r3_b:`2 divisions`,table_r3_c:`4 divisions`,table_r3_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r4_a:`Borders that follow existing municipal lines`,table_r4_b:`80% — within norm`,table_r4_c:`72% — within norm`,table_r4_d:`N/A — both within Canadian norm (70–85%)`,table_r5_a:`Boundaries flagged by the commission chair`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`N/A`,table_r6_a:`Seats at 50/50 votes (percentile in 1,010,000-map simulation)`,table_r6_b:`46.1% — p83 (normal range)`,table_r6_c:`51.7% — p99.99 (fewer than 100 of 1,010,000 reach this)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Efficiency Gap (percentile in 1,010,000-map simulation)`,table_r7_b:`+0.04% — p15.5 (normal range)`,table_r7_c:`+3.96% — p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Packing-cracking neighbourhood pattern`,table_r8_b:`6 coupled chain signals`,table_r8_c:`2 (pre-registered PASS)`,table_r8_d:`Neutral — minority achieves partisan effect via hybridization, not adjacency drain (§5.3.5)`,vocab_label:`VOCABULARY`,vocab_eg:`<strong>Efficiency gap.</strong> A single number that measures how lopsidedly a party's votes are translated into seats. Positive numbers favour the UCP; negative favour the NDP. The audit uses ~5% as Alberta's outlier line — the value exceeded by only 5% of the 1,010,000 neutral Alberta-specific simulations. This threshold is not borrowed from US or general literature; a threshold calibrated to another jurisdiction would be wrong because Alberta's natural geography produces a different neutral range.`,vocab_mm:`<strong>Mean-median difference.</strong> The gap between a party's median district vote share and its mean district vote share. When one party wins many close races, the median sits above the mean — those votes are distributed efficiently. When a party wins many races by large margins, the mean sits above the median — votes are being wasted. A large mean-median gap in one direction flags structural inefficiency in how one side's votes are spread across districts.`,vocab_percentile:`<strong>Percentile ranking.</strong> In this audit, a "percentile" is a rank within the 1,010,000 neutral simulated maps. "p94" means 94% of neutral maps score lower — the real map is more extreme than 94% of neutral draws. "p99.99" means fewer than 1 in 10,000 neutral maps reach the level.`,vocab_anchoring:`<strong>Anchoring.</strong> The fraction of an electoral border that lies on a pre-existing administrative line — a city limit, a school-division boundary, a Statistics Canada census line.`,closing_p1:`The bottom rows depend on election results. The <em>seats@50/50</em> test holds the electorate at perfect parity (UCP and NDP each win exactly half the votes province-wide) and asks how many seats the map awards the UCP. A neutral Alberta map produces a median around 44.8% UCP seats. Alberta's geography — NDP voters concentrated in city cores, UCP voters spread across rural ridings — gives the NDP a small efficiency advantage at neutrality. The majority map at 46.1% sits at the 83rd percentile of the 1,010,000-map simulation, well inside the normal range. The minority map at 51.7% sits at the 99.99th percentile: fewer than 100 of 1,010,000 neutral draws reach that value. The <em>efficiency gap</em> number measures how lopsidedly each party's votes get translated into seats. On the official Elections Alberta shapefiles the minority's efficiency gap is +3.96%, placing it at the 94.4th percentile — just below the audit's 95th-percentile outlier line. The opening questions at the top of this page unpack the consequences.`,closing_p2:`The last row is where the minority map has fewer coupled chain signals than the majority on the neighbour-drain test: 2 against the majority's 6 (and the 2019 enacted map's 5). The audit pre-registered this test before measuring, and the minority's lower count is a genuine pre-registered PASS — the minority does not show the classic pack-and-drain adjacency pattern. It is the single test where the minority numerically outperforms the majority. §5.3.5 of the academic report explains why: the minority achieves its partisan effect through hybridization (city-splitting that internalises packing and cracking within individual EDs), which is invisible to an adjacency-chain test that only measures how packed districts cluster next to cracked ones.`},commission_split:{heading:`2: How the Commission Split`,intro:`Alberta's Electoral Boundary Commission finished its work on March 23, 2026 and could not agree. Three commissioners produced one map; the other two produced a different one. Commission Chair Justice Dallas K. Miller and two opposition-nominated commissioners wrote the majority report; two government-nominated commissioners — Dr. Julian Martin and John D. Evans — wrote the minority report. The split centred on how to draw boundaries in fast-growing urban-edge communities. The majority gave Airdrie two districts; the minority four. The majority drew northwest Calgary's divisions close to the provincial average; the minority drew them 11.5% above it. Both maps follow the same statute. Both are legal under the <em>Electoral Boundaries Commission Act</em>. The disagreement was about which specific geographic configurations best served the communities being drawn. Alberta's governing party is the United Conservative Party (UCP); its main opposition is the New Democratic Party (NDP). Smaller parties — the Alberta Party, the Liberal Party of Alberta, and others — contest seats too, but their combined provincial vote share has been low enough in recent elections that it does not materially affect the audit's partisan-fairness calculations, which are grounded in the 2023 UCP–NDP split. This audit measured both maps using the same methods, applied identically. Three findings stand out.`,finding1:`<strong>The two maps differ on six things you can measure without looking at any election results:</strong> how evenly people are spread across districts, whether voters are concentrated, how badly cities are cut up, whether borders follow city limits, the shape of the districts, and how many boundaries the commission's own chair flagged as anomalous. The minority map differs from the majority on every one of them.`,finding2:`<strong>Every measured difference moves in the same direction.</strong> Everywhere the two maps diverge — northwest Calgary, Airdrie, urban areas with clear city limits — the minority map draws boundaries that spread NDP votes thinner and let UCP votes count more efficiently. The communities most reshaped by the minority map are the same communities where the NDP is strongest. The audit cannot determine intent. It can measure effect.`,finding3:`<strong>The process now promoting the minority map has no precedent in Canada.</strong> No other province lets a cabinet hand redistricting to a committee its own party controls partway through a redistribution cycle. Most provinces either require the legislature to debate the commissioners' map first, or give the commission's map automatic effect unless overridden. Alberta does neither. On April 16, the government set both commission maps aside and assigned the work to an MLA committee a majority of whose members come from the governing United Conservative Party (UCP); the committee's full composition and mandate are detailed in §7. Alberta's <em>Electoral Boundaries Commission Act</em> requires the legislature to pass a separate Electoral Districts Act to give a commission report legal effect — the commission report itself changes nothing. Most other provinces make a commission's report legally effective unless the legislature actively overrides it; Alberta's default reverses it, meaning the governing party controls whether any commission map ever becomes law. The government's stated justification was to implement Commission Chair Justice Miller's Recommendation 5. But Miller had written the recommendation specifically to dissuade the legislature from accepting the minority map, and his majority colleagues did not endorse it. Recommendation 5 was also geographically specific: one additional rural seat south of Edmonton, and one in Clearwater County and western Mountain View County — both far from the fast-growing Calgary and Edmonton urban-edge communities where the commission actually split. It was not an invitation to redesign those contested boundaries. The government adopted the seat count while handing a committee it controls authority over exactly the lines the commission disagreed on.`,closing:`<strong>The process is its own finding, separate from the maps.</strong>`},november:{heading:`7: The Lunty Committee`,context_label:`CONTEXT`,context_body:` — This section describes the process that replaced the commission and the legal framework that applies to it. It is not part of the statistical findings. The findings are in §3–§6 above.`,intro:`Neither commission map is in force. In April 2026 the government set both aside and referred redistricting to a Special Select Committee of five MLAs — three UCP, two NDP — chaired by Brandon Lunty (UCP, Leduc-Beaumont). The committee itself does not draw the map. It oversees a separate advisory panel of five appointees (a government-appointed chair, two UCP nominees, two NDP nominees) tasked with producing a 91-seat boundary proposal. The committee must deliver its report to the Legislature by November 2, 2026. Unlike the original commission, neither the committee nor the advisory panel is required to hold public hearings; the panel draws on submissions the original commission gathered. The all-party committee sought a retired or sitting judge to chair the advisory panel, but Alberta's acting chief justice declined to nominate one. When the committee's map is released, this audit will apply the same methodology to evaluate it.`,h_anomalous:`Why the Committee Is Anomalous`,anomalous_p1:`Canadian redistricting practice has, since the 1960s, settled on a single model: an independent commission, insulated from government direction, produces boundary recommendations; the legislature may debate them but cannot easily override them without a formal legislative vote. Alberta's statutory process under the <em>Electoral Boundaries Commission Act</em> follows this template — but with one structural difference from most provinces: Alberta's commission report has no automatic legal effect. Under the Act, a separate Electoral Districts Act must be passed by the legislature to give any commission map force of law. This means the government of the day controls not only whether the commission map is debated, but whether it ever becomes law at all. Other Canadian jurisdictions take the opposite default: the commission's recommendations take effect unless the legislature affirmatively votes to override them.`,anomalous_p2:`What the government did in April 2026 has no recorded precedent in post-Confederation redistricting: it allowed a completed, published commission process to conclude — both majority and minority reports filed — and then referred the redistricting task to a five-member committee of MLAs whose majority (three of five) is held by the governing party, without bringing either commission report to a vote. The Lunty committee is not a commission. It has no statutory independence from the government's legislative direction. Its three-member UCP majority mirrors the government's control of the legislature. No other Canadian province has transferred redistricting authority, mid-cycle, to a government-controlled legislative committee after an independent commission had completed its work.`,h_framework:`The Constitutional Framework`,framework_p1:`Section 3 of the <em>Charter of Rights and Freedoms</em> — "Every citizen of Canada has the right to vote in an election of members of the House of Commons or of a legislative assembly" — has been interpreted by the Supreme Court of Canada to guarantee not merely the act of casting a ballot but <em>effective representation</em>. The leading authority is <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, in which McLachlin J. (as she then was) wrote for the majority that the purpose of s.3 "is not equality of voting power per se, but the right to effective representation." Population parity is the primary consideration; departures are permitted when justified by community of interest, geography, history, or minority-representation objectives.`,framework_p2:`The Saskatchewan framework does not categorically prohibit partisan considerations in redistricting. What it establishes is that boundary maps must, on the whole, provide effective representation to voters — and that systematic impairment of one identifiable group's ability to elect proportionate representation is the pattern that s.3 challenges target. The audit's statistical and structural findings — the minority map's position at the 99.99th percentile of 1,010,000 neutral draws, its crossing of four of five structural thresholds (the fifth, anchoring, is neutral for both maps), the identified communities affected — are the evidentiary record a s.3 applicant would need to assemble. On the community-of-interest side of that record, the Federal Court's decision in <em>Raîche v. Canada</em> (2004 FC 679) is the leading Canadian authority: the court there required the federal Electoral Boundaries Commission to revisit boundaries that had ignored Acadian community of interest in New Brunswick. The audit's municipal-anchoring measurements and its specific community findings — Airdrie split into four districts, the chair-flagged urban-edge anomalies in northwest Calgary — are the same kind of evidence the Federal Court treated as legally cognizable. Whether that record meets the constitutional threshold is a legal question this audit does not decide; the audit reports the measurement.`,framework_p3:`The committee's legality as a process is a separate question. Alberta's <em>Electoral Boundaries Commission Act</em> does not expressly prohibit the legislature from constituting a parallel redistricting body, because the Act contemplates that the legislature will enact the final boundaries through ordinary legislation regardless. Whether the committee process, if it produces a map with the structural and statistical profile of the minority proposal, could survive a s.3 Charter challenge turns on whether effective representation is achievable under the resulting boundaries — the same test that would apply to any commission-produced map.`,h_quebec:`The Quebec Contrast`,quebec_p1:`Quebec offers the comparison most relevant to Alberta's situation. Quebec's Commission de la représentation électorale (CRE) is a permanent, independent electoral boundaries body, not an ad hoc commission constituted per redistribution cycle. The CRE operates continuously and cannot be dissolved or bypassed by cabinet action. Under Quebec's <em>Loi électorale</em>, the National Assembly must adopt the CRE's recommendations unless it votes to deviate — and deviations require a two-thirds majority of all members of the Assembly, not a bare legislative majority. The practical effect is that a governing party cannot, acting alone with its own majority, substitute its preferred map for the commission's. Cross-party agreement is constitutionally required to override the independent body's judgment.`,quebec_p2:`Quebec's model emerged partly from lessons about what happens when redistricting is not insulated from partisan control. The contrast with Alberta's current process — where a majority-controlled committee has replaced the commission's work before the legislature has voted on either commission report — illustrates the structural difference between redistricting systems that assume partisan pressure and design against it, versus systems where that pressure has a clearer path to the outcome.`,closing:`The audit will apply the same tests to the Lunty committee's map when it is released. The constitutional and comparative observations above are contextual; the methodology does not change.`},references:{heading:`10: References and Methodology`,heading_aria:`Link to references`,intro:`The underlying methodology draws on established political science, statistics, and legal literature. Full citations follow American Political Science Association (APSA) style; court cases follow Canadian legal convention. The complete reference list appears in the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">technical report</a>. Key sources are listed here.`,h_academic:`Academic literature`,h_cases:`Court cases`,h_statutes:`Statutes`},resources:{heading:`11: Technical Appendix`,heading_aria:`Link to technical`,tag_plain:`Plain Language`,plain_label:`Full public report`,plain_desc:`Long-form, with maps, for general readers`,tag_summary:`Summary`,summary_label:`Summary of findings`,summary_desc:`Plain-language overview, explains every concept from scratch`,tag_academic:`Academic`,academic_label:`Technical report`,academic_desc:`Full methods and citations for researchers`,tag_notebook:`Notebook`,notebook_label:`Interactive notebook`,notebook_desc:`Run the charts yourself in your browser, no install needed`,tag_code:`Code`},about_me:{heading:`About me`,p1:`I'm a student at Mount Royal University. I did this research on my own — it was not assigned as coursework and the university did not commission it. My views are my own and do not represent the university. I have no connection to Elections Alberta, the commission, or any political party.`,p2:`I have voted for different parties in different elections, across the political spectrum. I'm telling you because my political history could affect how I look at this issue. The main protection against it is the method: I tested both maps the same way, wrote down my predictions before looking at the results, and put everything online so anyone can check my work. I paid for this research myself. If you find something I got wrong, I genuinely want to know.`,p3:`Pre-registration records (written before results were examined): <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451.`,p4:`Questions or corrections: <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9: Retractions and Corrections`,heading_aria:`Link to retractions`,conditions_label:`RETRACTION CONDITIONS`,conditions_intro:`Every finding is pre-committed to a specific falsification condition. If any condition below materialises, the finding it names is retracted publicly within 30 days. The overall directional conclusion — that the minority map sits outside the neutral range on multiple independent tests — is retracted only if at least three of the five tests fail.`,c1_title:`Condition 1 — A counter-map exists`,c1_what:`<em>What gets retracted:</em> The structural finding that the Airdrie four-way split and the three chair-flagged boundaries cannot be explained by the minority's stated community-of-interest rationale.`,c1_cond:`Condition: someone produces a legal Alberta map satisfying the minority's own stated reasons — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — and anchors on municipal lines at majority-comparable rates. Open challenge at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,c2_title:`Condition 2 — The Neighbour-Drain pre-registered pass is reversed`,c2_what:`<em>What gets retracted:</em> The Section 3 table entry recording the minority map as a pre-registered PASS on the neighbour-drain adjacency test.`,c2_cond:`Condition: the v2 continuous drain score falls in the extreme upper tail (p &lt; 0.05) of random permutations across the fixed contiguity graph, meaning the pass was a measurement artefact of the v1 binary scoring method rather than a genuine null result.`,c3_title:`Condition 3 — A pre-2026 commission document surfaces`,c3_what:`<em>What gets retracted:</em> The inference that the minority's boundary choices were drafting decisions rather than responses to documented community submissions.`,c3_cond:`Condition: an internal commission document dated before the minority's final boundary choices shows those choices were explicitly driven by community submissions the audit has not seen — not by the six published sub-rationales the audit tested.`,c4_title:`Condition 4 — The 2027 election result contradicts the simulation`,c4_what:`<em>What gets retracted:</em> The Lane 1 finding — that the minority map's seats@50/50 score sits at the 99.99th percentile of 1,010,000 neutral draws.`,c4_cond:`Condition: if the 2027 provincial election is fought on either commission map and the actual partisan seat split contradicts the directional projection from 2023 votes, the Lane 1 percentile findings are revisited against actual results.`,c5_title:`Condition 5 — An Alberta court distinguishes the Quebec SCC ruling`,c5_what:`<em>What gets retracted:</em> The Section 7 procedural argument that the April 16 motion to replace the commission with the Lunty committee sits in the same constitutional class as Quebec's 2024 redistricting freeze.`,c5_cond:`Background: on April 22, 2026 — six days after Alberta's April 16 motion — the Supreme Court of Canada upheld, 7–2 and from the bench, a Quebec Court of Appeal ruling that the Legault government's legislative freeze on its redistricting commission violated the Charter's s.3 democratic-representation guarantee. Condition: a court reviewing the Alberta motion finds it constitutionally distinct — for example, because reassigning the work to an MLA committee differs structurally from a legislative freeze, or because Alberta's effective-representation analysis under s.3 comes out differently than Quebec's.`,corr_label:`DOCUMENTED CORRECTIONS (canonical recomputation, 2026-05-11)`,corr_intro:`The following early finding did not survive reanalysis against official Elections Alberta shapefiles (received 2026-05-06). It is retained here per the audit's pre-committed policy of never deleting failed findings.`,corr_municipal:`<strong>Municipal anchoring (retracted).</strong> Early analysis using provisional map boundaries showed the minority map anchored to municipal lines only 15% of the time — 4.9&times; below the 70–85% Canadian norm. This figure was an artefact of the provisional (DPG-era) boundary reconstructions. On official Elections Alberta canonical shapefiles, both maps anchor within the Canadian norm: majority 80%, minority 72%. The municipal-anchoring <em>divergence</em> between the two maps is not a signal that survives canonical recomputation. The three boundary anomalies flagged by the commission chair (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie) remain and are not affected by this correction.`},suggestions:{heading:`8: Suggestions`,heading_aria:`Link to section 8`,intro:`This audit ran into two data problems that have nothing to do with the commission's work and everything to do with how Alberta's electoral system is designed. Both are fixable.`,advance_p1:`<strong>About half of all Alberta votes now arrive before election day</strong> — advance polls, mobile polls, special ballots. Elections Alberta reports these results as totals for each electoral division, not by specific Voting Area. This means roughly 395,000 NDP and UCP votes cast in 2023 cannot be pinned to any neighbourhood on a map. They are counted; they just can't be located. Every advance voter is checked against a voters list before receiving their ballot, and the list links each voter to their specific Voting Area. Publishing VA-level advance-vote totals would not require any change to the voting process — only to what EA reports.`,advance_p2:`This affects the commissioners too, not just outside analysts. When a commission decides whether to keep Airdrie whole or split it, whether a corridor between two communities makes sense, whether a proposed boundary divides a natural constituency — those are judgments that depend on knowing where voters live. Commissioners work from the same published dataset as everyone else. Half the geographic signal about the communities they are drawing boundaries around is missing for them as well.`,lesser_slave_p1:`There is at least one community in northern Alberta where this gap is total. In the northern part of the Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">show ↗</button> division, there is a Voting Area covering 4,832 km&#178; — larger than Prince Edward Island — where every single vote in 2023 was cast through Elections Alberta's mobile polling team. Those 844 residents' choices are counted in the divisional total but cannot be pinned to any location on a map. The community is entirely invisible in the published election results.`,lesser_slave_p2:`When the commission initially considered eliminating the Lesser Slave Lake division and merging it into a larger riding, it was working without geographic vote data from those communities. The commission eventually preserved the division — after 80+ public submissions, many from the Indigenous communities in the northern part of the riding — invoking a provincial law that allows ridings with First Nations and M&#233;tis communities to have smaller populations than the provincial average. They got there. But the data they were working with didn't show them who was voting in the communities they were deciding to protect.`,ebca_label:`SECTION 15(2) EBCA`,ebca_body:`Section 15(2) of Alberta's <em>Electoral Boundaries Commission Act</em> is a discretionary provision that allows commissions to protect undersize ridings — those more than 25% below the provincial population average — when the riding meets at least three of five specific criteria: (a) geographic area exceeding 20,000 km², (b) distance more than 150 km from the Legislature Building by most direct highway route, (c) absence of any town with more than 8,000 residents, (d) presence of an Indian reserve or a Métis settlement, and (e) whether the riding is coterminous with a boundary of the Province of Alberta. The provision is not automatic; the commission must judge whether the criteria are met. Lesser Slave Lake independently meets four of the five.`,rationale_p1:`The interim rationale for eliminating the riding was population: at roughly 27,000 residents, Lesser Slave Lake sits about 45% below the provincial average, approaching the legal floor. This reads as a straightforward application of the rules. It isn't. Alberta law gives commissions explicit discretion to protect undersize ridings when at least three of five specific criteria apply, and Lesser Slave Lake meets four of them independently. Its area is 69,566 km² (criterion a, threshold 20,000 km²). Its nearest boundary is more than 150 km from the Legislature by highway (criterion b). No town in the riding has a population over 8,000 (criterion c). And the riding contains fourteen Indian reserves and M&#233;tis settlements whose communities share a common northern geography, a common dependence on mobile polling to vote at all, and a collective interest in having a representative primarily accountable to northern Alberta (criterion d).`,rationale_p2:`Under the proposed Mackenzie merger, the collective voice would have been permanently absorbed into a riding where the other party wins by more than two to one, not because those communities changed but because the lines around them did. Each of those four criteria is an objective fact about the riding's geography, not a judgment call. Together they describe a constituency the provision was written to protect: remote, large, sparsely populated, and containing communities whose representation interest cannot be read from raw population numbers. You need three to qualify; Lesser Slave Lake has four. Treating the population shortfall as if it compelled elimination misreads the statute. The commission's reversal was the correct application of the law, not a concession to political pressure.`,banff_p:`Here is the other side of the story: while the Indigenous communities in Lesser Slave Lake were fighting to be counted, the dissenting commissioners proposed protecting a different riding by drawing its boundary through Banff National Park, where no one lives. The commission's own chair called it "a bad faith effort" to claim the legal protection. The phrase is in the commission's official final report. The protection designed for remote communities with Indigenous populations was used, in the minority's map, to defend a boundary through uninhabited wilderness. The communities it was designed to help had to fight for it through public submissions. The Lunty committee will face the same §&#x2009;15(2) decision in November — with no statutory requirement to hold public hearings, and no guarantee the 80 submissions reversing the commission's interim position will carry the same weight a second time.`,census_p1:`<strong>Alberta should wait for the 2026 census before drawing the next map.</strong> Canada counts its population every ten years. The 2026 census enumeration happens in spring 2026; Statistics Canada releases usable sub-provincial data roughly two years later, in 2027 or 2028. The commission that drew the maps assessed in this audit had to use the 2021 census — already four years old when the maps were drawn, and potentially fourteen years old by the time those boundaries retire. Fast-growing cities like Airdrie and Chestermere will change by 40% or more over that window. Rural communities will shrink. The map will be wrong from the day it is used. A straightforward change to the <em>Electoral Boundaries Commission Act</em> could require that any new commission be appointed only after Statistics Canada releases the most current dissemination-area data from the preceding census. The result: maps that reflect where Albertans actually live, not where they lived a decade ago.`,census_p2:`The Lunty committee is operating under the existing statute, which sets no census-timing requirement, and cannot unilaterally delay past its November 2026 deadline. This recommendation applies to a future amendment to the <em>Electoral Boundaries Commission Act</em>, not to the current process. The tension is real: a committee required to deliver a map by November is working from data already five years old by then — naming the constraint is more useful than pretending it does not exist.`,closing:`Neither of these is a finding about the current commission's maps. They are observations about a system that makes accurate electoral analysis harder than it needs to be. They are offered here as practical suggestions, not conclusions. Both are genuinely fixable, and fixing them would make every future commission — and every future audit — work from better ground.`}},editorial_canada:{heading:`Context: Canada is different — and similar`,p1:`Canada belongs to the same family as the U.S., the U.K., and Australia. We elect single members from geographic districts under first-past-the-post. We redraw the lines periodically — federally after each decennial census, provincially on staggered schedules. We inherited the basic machinery from the same Westminster roots. So far, no surprises.`,p2:`What sets Canada apart is the test the lines have to pass.`,p3:`In American constitutional law, the binding rule is <em>one person, one vote</em> — districts must have populations as nearly equal as practicable, and large departures require strict justification. In Canadian constitutional law, the binding rule is different. Section 3 of the <em>Canadian Charter of Rights and Freedoms</em> guarantees every citizen the right to vote. In <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — the 1991 Saskatchewan Reference, the leading case — the Supreme Court of Canada interpreted the right as a right to <em>effective representation</em>, not a right to mathematical equality of district populations.`,p4:`That distinction matters. Effective representation allows district populations to vary, sometimes substantially, when there are good reasons: vast rural geographies one MLA cannot reasonably serve at standard population density, communities of interest that should be kept together, minority representation that mathematical equality would dilute. The Saskatchewan Reference made that flexibility constitutional. The EBCA's 25% population variance — the rule that protects rural Alberta seats — flows directly from it.`,p5:`The catch is that flexibility cuts both ways. If a commission can legitimately depart from population equality for the right reasons, it can also depart from population equality for the wrong ones. Canadian law has no American-style mathematical floor to fall back on. It has the effective-representation test, applied by judges, after the fact, in litigation. Most jurisdictions guard against the wrong reasons with structural protections: federal redistricting commissions are insulated by statute and their recommendations take effect automatically if Parliament does not act on them within a deadline. Quebec uses a permanent independent commission whose work the National Assembly can override only with a two-thirds supermajority. British Columbia operates under a similar default-adopt rule.`,p6:`Alberta is the exception. Under the <em>Electoral Boundaries Commission Act</em>, the commission's report is a recommendation only — the legislature must vote to enact it. Approval is normally a formality. In the 2026 cycle, the commission split 3–2 and produced two competing proposals; the legislature created a separate MLA committee, chaired by a Premier-appointed MLA, to choose between them. Nothing in Canadian constitutional law required the committee to exist. Nothing requires its choice to follow the commission's process. This is the structural gap this audit is examining.`,p7:`So when Canadian courts say "gerrymander" isn't their legal vocabulary, they are not saying the underlying concept does not apply here. They are saying the test is different — effective representation, not mathematical equality. Whether the minority proposal meets that test is exactly the question this audit has measured the geometry against, and exactly the question only a judge can answer definitively. The <em>Saskatchewan Reference</em> reasoning in full, the contrast with other provinces, the standing question, and the available reform pathways are treated in <a href="#references">the references section below</a>.`},chrome:{back_to_top:`Back to top`,license_title:`Creative Commons Attribution-NonCommercial-ShareAlike 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Back to Stakes`,lightbox:{fig_aria:`Figure enlarged view`,fig_close_aria:`Close enlarged figure (Esc)`,map_aria:`Map zoom viewer`,map_close_aria:`Close map viewer`,close_title:`Close (Esc)`},participation:{heading:`Help us refine MapExplorer`,body:`As you explore, we track which maps and districts you visit and periodically send the data to our research database. Sharing a view also saves where you ended up. The goal: understand what's useful and make the tool better.`,no_collect:`We never collect your name, IP address, or precise location. Everything is anonymized in your browser before it leaves. We couldn't identify you from the data even if ordered to.`,dnt:`Your browser has Do Not Track enabled. No is pre-selected on your behalf. You can still choose Yes.`,no_thanks:`No thanks`,yes_help:`Yes, I'll help`,privacy_policy:`Privacy policy`},share:{button:`Share`,button_title:`Share or load a map configuration`,dialog_aria:`Share map configuration`,close_aria:`Close share panel`,share_label:`Share this configuration`,share_hint:`Type this code into any browser running the audit to load this configuration. The code is never placed in a URL.`,load_label:`Load a configuration`,load_btn:`Load`,load_placeholder:`alpine-eagle-banff`,copy:`Copy`,copied:`Copied!`,copy_failed:`Failed`,unrecognised:`Unrecognised code — check spelling.`},map:{minority:`Minority`,majority:`Majority`,current:`Current`,wasted:`Wasted`,wasted_title:`Efficiency-gap contribution per district`,partisan:`Partisan`,partisan_title:`Colour each district by partisan outcome (UCP blue / NDP orange)`,borders:`Borders`,flagged:`Flagged`,flagged_title:`All 7 configurations flagged by commission chair Justice Miller — switches to minority map automatically`,help_aria:`Map help`,help_title:`How to use the map`,pin_aria:`Pin Map`,pin_title:`Pin Map — prevent auto-pan on district click`,search_placeholder:`Find district…`,zoom_aria:`Map zoom`,clear_aria:`Clear district selection`,clear_title:`Clear selection`,va_hint:`Click within this district to see polling station results`,va_close_aria:`Close polling station detail`,va_close_title:`Close`,object_title:`Alberta electoral district map — full resolution`,ea_credit:`Map data:`,cc_title:`Text content: CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`},map_intro:{heading:`How to use the map`,click_district:`Click any district`,click_district_desc:`see 2023 election results and snap to it`,click_within:`Click within a selected district`,click_within_desc:`see individual polling station results (colour = vote split)`,dblclick:`Double-click a district`,dblclick_desc:`zoom to fill screen; double-click empty space to zoom out`,layers_primary:`Minority / Majority / Current`,layers_primary_desc:`switch the active boundary map`,layers_data:`Partisan / Wasted / Borders`,layers_data_desc:`toggle data layers`,search:`Find district`,search_desc:`jump by name; arrow keys pan, + / − zoom`,escape:`Escape`,escape_desc:`close this viewer`,s4_tip:`In §4, click <em>Show flagged districts on map</em> to highlight the Airdrie split and NW Calgary zone.`,got_it:`Got it`},footer:{title:`Alberta Electoral Boundary Audit — May 2026`,copyright:`© Will Conner 2026 —`,text_label:`Text:`,code_label:`Code:`}}},fr:{selector:{label:`Choisir la langue`},disclaimer:{text:`Ce site a été traduit par IA. Certains contenus peuvent encore apparaître en anglais pendant que les traductions sont en cours. Si vous remarquez des erreurs ou souhaitez aider à traduire ce projet, n'hésitez pas à %s.`,link_label:`nous contacter`},opener:{heading:`À qui s'adresse ce document ?`,body:`À nous. À nous tous. Aux ruraux, aux urbains, aux curieux, aux mordus de politique, aux journalistes, aux avocats, aux universitaires, aux élus — à nous tous. Parce que cela nous touche tous. Que vous aimiez ou non le parti au pouvoir, ce que la commission divisée a produit ne s'était jamais vu auparavant. Et cela nous donne l'occasion d'observer la mécanique de l'intérieur comme nous n'avions jamais pu le faire. Nous pouvons maintenant établir un point de repère — une série de tests, et tout ce qui suivra pourra être évalué à cette aune. Laissez-moi vous montrer ce que j'ai trouvé.`},stakes:{q1:{heading:`La carte proposée est-elle un découpage partisan ?`,body:`« Gerrymander » n'est pas un terme employé par les tribunaux canadiens. Mais s'il l'était — au sens courant que la plupart des gens lui donnent — les éléments de cet audit appuieraient raisonnablement la qualification de la <em>proposition minoritaire</em>, si elle était adoptée, comme une carte fortement remaniée à des fins partisanes. Tous les tests structurels de cet audit signalent la <em>proposition minoritaire</em> ; aucun ne signale l'autre (la <em>proposition majoritaire</em>).`,footnote:`Les noms « majorité » et « minorité » proviennent d'une division 3 contre 2 au sein de la Commission de délimitation électorale (présidée par le juge Miller), qui a produit deux propositions concurrentes plutôt qu'une seule recommandation. Un comité distinct de MLA présidé par Brandon Lunty — un MLA nommé par le Premier ministre — choisit actuellement entre les deux avant la date limite de novembre 2026.`},q2:{heading:`Que signifie « gerrymander » en droit canadien ?`,body:`Rien. Le critère canadien est différent : il s'agit de savoir si les limites garantissent aux électeurs une <em>représentation effective</em> au sens de l'article 3 de la Charte. La proposition minoritaire soulève de sérieuses questions sous ce critère ; seul un juge peut y répondre de façon définitive, et personne n'en a saisi un.`},q3:{heading:`Qu'est-ce que cela signifie pour les Albertains ?`,body:`Lors d'un vote provincial à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel — moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Ce déséquilibre compte parce qu'à 58 sièges sur 87 — une majorité des deux tiers — le parti au pouvoir débloque des pouvoirs procéduraux exceptionnels : il peut écarter les délais d'avis habituels et faire franchir à un projet de loi public plusieurs étapes législatives en une seule journée, contournant les freins délibératifs qui le contraignent normalement. Savoir si l'inclinaison de la proposition minoritaire est assez forte pour porter un parti au-delà de ce seuil de 58 sièges à des résultats de vote <em>autres</em> que 50/50 est une question que cet audit n'a pas encore examinée. Savoir si le compromis lui-même est acceptable est une question pour les Albertains, et non pour cet audit.`},cta_law:`Lire le contexte juridique →`,cta_methods:`Voir notre méthodologie →`},head:{title:`Audit des limites électorales de l'Alberta`,meta_description:`Audit statistique de la commission albertaine de délimitation électorale de 2026 — 1 010 000 cartes neutres, fichiers officiels d'Elections Alberta, tests pré-enregistrés.`},nav:{home_aria:`Retour en haut`,theme_aria:`Basculer le mode sombre / clair`,theme_title:`Basculer le mode sombre`,nav_aria:`Basculer la navigation`,drawer_top:`↑ Haut`,stakes:`Stakes`,why:`Pourquoi ?`,map:`Carte`,split:`La Division`,litmus:`Test décisif`,crack_pack:`Diviser et entasser`,for_you:`Pour vous`,impact:`Conséquences`,history:`Histoire`,canada:`Canada`,gerrymanders:`Découpages partisans`,november:`Novembre`,lunty:`Lunty`,invisible:`L'invisible`,suggestions:`Suggestions`,retractions:`Rétractations`,references:`Références`,resources:`Ressources`,technical:`Technique`},hero:{h1:`Audit des limites électorales de l'Alberta`,subtitle:`La commission albertaine a produit deux cartes de circonscriptions en 2026. Cet audit les a comparées — en appliquant les mêmes tests, également aux deux — pour déterminer si elles traitent les électeurs de la même manière.`,badge:`Cartes officielles d'Elections Alberta — publiées en mai 2026`,cover_note:`Cliquez pour zoomer et explorer les trois propositions simultanément. Verrouillez la vue et passez d'une carte à l'autre — les frontières bougent, les électeurs restent. Faites défiler pour voir l'analyse.`,cover_note_1:`Cette carte est la meilleure porte d'entrée. Cliquez pour zoomer et explorer. Les boutons en haut permettent de basculer entre la proposition minoritaire, la proposition majoritaire et les limites adoptées en 2019 — ou de superposer les trois pour voir exactement où elles divergent. <strong>Detail</strong> colore chaque zone de vote selon le résultat de 2023 ; <strong>Trend</strong> ajoute un ombrage partisan par circonscription (bleu UCP, orange NDP) ; <strong>Lines</strong> active ou désactive les limites. <strong>Find</strong> permet de trouver une circonscription par son nom.`,cover_note_2:`Essayez de verrouiller l'affichage et de passer d'une carte à l'autre — observez une limite se déplacer tandis que les électeurs en dessous restent en place. C'est toute la question en un seul geste.`,cover_note_3:`Quand vous avez fini d'explorer, faites défiler vers le bas pour le résumé. Pour l'analyse technique complète, voir la section Ressources. Toutes les données proviennent des fichiers officiels d'Elections Alberta et d'autres sources gouvernementales et ouvertes.`,image_alt:`Cartes des circonscriptions électorales de l'Alberta — proposition minoritaire de la commission, coloriée selon les votes de 2023`,map_hint:`Cliquer pour explorer de façon interactive`,btn_title:`Cliquer pour ouvrir la carte interactive`,btn_aria:`Ouvrir la carte interactive`},boundary:{heading:`Ce que cet audit peut et ne peut pas vous dire`,can_1:`Moins d'une carte sur 14,5 millions de cartes de comparaison générées aléatoirement a produit des motifs aussi extrêmes que la proposition minoritaire sur l'ensemble des quatre mesures statistiques combinées.`,can_2:`La proposition minoritaire échoue à 5 des 5 tests structurels pré-enregistrés. La proposition majoritaire échoue à 0 sur 5.`,can_3:`Ces résultats sont cohérents avec des cartes qui produisent de forts effets partisans, et incohérents avec ce que produit l'ensemble de comparaison aléatoire.`,cant_1:`L'audit n'établit <strong>pas</strong> qu'un commissaire ait eu l'intention de produire les effets partisans mesurés. La géométrie des limites ne peut révéler l'intention.`,cant_2:`L'audit ne prédit <strong>pas</strong> ce que le comité Lunty choisira, ce que sera le vote de novembre 2026, ni comment les Albertains réagiront.`,cant_3:`L'audit ne prédit <strong>pas</strong> comment un tribunal trancherait si une contestation fondée sur la Charte était intentée contre l'une ou l'autre proposition.`,cant_4:`L'audit ne dit <strong>pas</strong> à un électeur quelle position adopter ni quoi faire de cette information. Cela vous appartient.`},editorial_intro:{heading:`Qu'est-ce que la redéfinition des circonscriptions et pourquoi devriez-vous vous y intéresser ?`,p1:`Chaque électeur de l'Alberta vit dans une <em>circonscription électorale</em> — une portion de la province qui élit une personne à l'assemblée législative. Il y a 87 circonscriptions. Chaque circonscription élit un MLA. Quand vous votez à une élection provinciale, vous choisissez le MLA de la circonscription où vous habitez. C'est tout le lien que la plupart des Albertains entretiennent avec l'assemblée législative : un MLA, une circonscription, un vote.`,p2:`Ces limites ne sont pas permanentes. Les gens déménagent, les quartiers grandissent, les régions rurales se vident, les villes s'étendent. Tous les huit à dix ans, l'Alberta est censée redessiner les limites pour que chaque circonscription soit à peu près de la bonne taille et reflète la façon dont les Albertains vivent réellement aujourd'hui. L'organisme qui s'en charge est la <em>Commission de délimitation électorale</em> — une commission indépendante composée de juges, d'avocats et de membres du public, et non de politiciens.`,p3:`C'est le processus standard. Cette fois, le processus standard a produit quelque chose d'inhabituel. Les cinq membres de la commission se sont divisés 3 contre 2 sur ce à quoi la carte devait ressembler et, plutôt que de s'entendre sur une seule recommandation, ils en ont produit deux : une <em>proposition majoritaire</em> (appuyée par trois commissaires) et une <em>proposition minoritaire</em> (appuyée par deux). Les deux sont sur la table. Un comité distinct de MLA présidé par Brandon Lunty — nommé par le Premier ministre pour cette décision précise — est en train de choisir entre les deux. L'assemblée législative doit approuver celle qui survivra à ce comité avant novembre 2026.`,p4:`Pourquoi cela compte pour vous : les limites décident qui est votre MLA. Elles décident quels quartiers, quelles villes et quelles préoccupations sont représentés ensemble. Si votre ville est divisée entre quatre MLA plutôt qu'un seul, aucun représentant unique n'est responsable de la ville dans son ensemble. Si votre communauté d'intérêts — une petite ville, une région rurale, un centre-ville — est divisée entre plusieurs circonscriptions, votre voix sur les décisions provinciales est diluée. La carte façonne aussi quel parti peut former un gouvernement, et à quelle marge. La conclusion précise de cet audit (que la proposition minoritaire se situe dans un extrême structurel) est la raison pour laquelle vous lisez ce site, mais la question plus large est plus ancienne et s'applique à chaque cycle de redécoupage : les limites reflètent-elles la façon dont les Albertains vivent, ou façonnent-elles la politique qui suit ?`,p5:`Le reste de cette page parcourt ce que les deux cartes proposées font réellement.`},editorial_reflect:{heading:`Ce que cela signifie pour vous et votre communauté`,intro_p1:`Mettons de côté, pour un instant, la question de savoir quel parti gagne ou perd des sièges. Les politiciens et les partis tendent à présenter cela comme une lutte pour la concentration du pouvoir à l'assemblée législative, et à cette échelle c'en est une. Mais la concentration du pouvoir à l'assemblée n'est pas là où vous vivez ces cartes. Vous les vivez à travers trois questions concrètes sur votre propre circonscription :`,intro_q1:`Où vit votre MLA ?`,intro_q2:`Est-il investi dans votre communauté ?`,intro_q3:`Les exigences de la tête vont-elles dominer celles de la queue ?`,intro_p2:`Tout autre cadrage — avantage partisan, seuil de supermajorité, extrême statistique — renvoie en fin de compte à ces trois questions. Les cinq échelons ci-dessous parcourent la manière dont chaque carte proposée y répond, à cinq échelles.`,you_h:`Vous.`,you_p:`Votre circonscription électorale décide qui vous représente à l'assemblée législative. En ce moment, vous vivez dans l'une des 87 circonscriptions. Sous les deux cartes proposées, vous pourriez vous retrouver dans une autre — possiblement avec un autre MLA, possiblement rattaché à des communautés voisines différentes. Si vous ne savez pas dans quelle circonscription vous êtes en ce moment, ou qui est votre MLA, vous n'êtes pas seul : la plupart des Albertains ne sauraient nommer leur MLA. Mais les limites ne sont pas abstraites. Elles décident dont le numéro de téléphone est sur le mur du bureau de votre représentant local, dont la pétition de quartier porte votre nom, dont les préoccupations votre MLA entend en premier. La recherche par code postal sur ce site indique dans quelle circonscription vous vous trouvez sous chaque proposition. Si votre circonscription change, votre représentant change — et la relation de votre représentant avec votre communauté change avec lui.`,community_h:`Votre communauté.`,community_p:`Les communautés ne sont pas abstraites non plus. La zone de fréquentation d'une école secondaire, une chambre de commerce, une communauté religieuse, une association de quartier — ce sont de véritables regroupements de personnes ayant des préoccupations locales communes. Lorsqu'une limite coupe à travers eux, aucun MLA unique n'est responsable de l'ensemble. Prenez Airdrie sous la proposition minoritaire : une ville d'environ 74 000 habitants découpée en quatre circonscriptions, chacune ancrée à un arrière-pays rural différent. Aucun représentant unique n'est responsable d'Airdrie comme ville. La même dynamique se joue partout où une ville, un quartier ou une communauté d'intérêts reconnue est divisée — plus la division est grande, plus la représentation est faible. L'audit mesure l'<em>ancrage municipal</em> (la fraction du périmètre de chaque circonscription qui suit les limites municipales existantes), et la proposition minoritaire obtient un score nettement inférieur à la majoritaire sur ce test.`,municipality_h:`Votre municipalité.`,municipality_p:`Lorsqu'une ville est fragmentée entre de nombreux représentants, sa capacité à négocier sur les décisions provinciales s'affaiblit. Un conseil qui demande du financement pour le transport en commun, une commission scolaire qui négocie une nouvelle école, un maire qui fait pression pour des prolongements d'autoroute — chacun de ces dossiers progresse mieux quand la ville peut s'appuyer sur quelques MLA qui doivent rendre des comptes à la ville dans son ensemble. La proposition minoritaire divise le quadrant nord-ouest de Calgary entre plusieurs circonscriptions dont les schémas de vote suggèrent l'<em>entassement</em> (concentrer les électeurs d'un parti dans quelques sièges à forte marge) en plus du <em>fractionnement</em> (répartir les électeurs de l'autre parti dans plusieurs sièges à faible marge). Savoir si ce schéma est intentionnel est une question à laquelle l'audit ne peut pas répondre — la géométrie des limites ne révèle pas l'intention. Ce qu'il peut dire, c'est que les quatre mesures statistiques signalent les mêmes circonscriptions que les tests structurels signalent, et que la proposition alternative ne produit pas la même empreinte.`,region_h:`Votre région.`,region_p1:`Si vous vivez en dehors des villes de l'Alberta, vous avez probablement remarqué que les conversations politiques sur les limites semblent toujours centrer les villes. C'est une plainte légitime, alors soyons directs sur ce que cet audit dit et ne dit pas sur l'Alberta rurale.`,region_p2:`Ce qu'il ne dit <strong>pas</strong> : que l'Alberta rurale a trop de sièges. La loi sur la délimitation électorale permet aux populations des circonscriptions de varier jusqu'à 25 % afin qu'un MLA rural ne représente pas une géographie de la taille du sud de la France. Les tribunaux canadiens traitent cette variance comme légitime. Les deux cartes proposées la préservent. Rien dans cet audit ne change cela.`,region_p3:`Ce qu'il <strong>dit</strong> : en plusieurs endroits sur la proposition minoritaire, des communautés rurales sont rattachées comme <em>queue</em> d'une circonscription dont le centre de population se trouve dans une ville. Regardez comment la proposition minoritaire traite Airdrie — une ville d'environ 74 000 habitants découpée en quatre circonscriptions, chacune prolongée dans un tronçon différent de la campagne rurale. Le centre de population de chaque nouvelle circonscription est la portion urbaine, pas la queue rurale. Un MLA élu d'une telle circonscription est le plus susceptible d'habiter, de faire campagne et de prioriser là où sont les voix — ce qui signifie que les communautés rurales autrefois représentées par un MLA rural dédié deviennent l'arrière d'un siège dirigé par la ville. Ce schéma se répète sur la proposition minoritaire d'une manière qu'il ne se répète pas sur la proposition majoritaire.`,region_p4:`L'audit ne propose pas de retirer des sièges à l'Alberta rurale. Il demande si les limites respectent les communautés rurales que ces sièges sont censés représenter, ou si la géographie rurale est utilisée comme ballast pour absorber les votes urbains dans des circonscriptions dont le centre est ailleurs. Si vous vivez dans l'une de ces queues rurales, la question de savoir laquelle des cartes sera adoptée décide si votre MLA représente la communauté rurale où vous vivez réellement, ou un district urbain dont les limites incluent simplement votre terrain.`,province_h:`Votre province.`,province_p:`L'assemblée législative est ce que vous obtenez quand vous additionnez les réponses de chaque circonscription aux trois questions ci-dessus. Si la plupart des circonscriptions sont ancrées à des communautés dont les MLA y vivent réellement, l'assemblée représente ces communautés. Si la plupart des circonscriptions ont des queues rurales rattachées à des têtes urbaines, l'assemblée représente les têtes — et les queues obtiennent l'attention qui reste. La question partisane — quel parti remporte la majorité — est en aval de cela. La question de la supermajorité — savoir si un parti franchit 58 des 87 sièges et débloque des raccourcis procéduraux comme la levée des délais d'avis ou l'accélération de projets de loi à travers plusieurs étapes en une seule journée — est en aval de <em>cela</em>. Lors d'un vote provincial hypothétique à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel : moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Savoir si ce déséquilibre porte un parti au-delà de 58 sièges aux résultats de vote que les Albertains livrent réellement est une question que cet audit n'a pas encore directement examinée ; les questions d'ouverture en haut de cette page sont honnêtes sur cette lacune. Savoir si la réponse à l'une de ces questions compte assez pour agir est, encore une fois, une question pour vous.`},editorial_history:{heading:`Une brève histoire du découpage partisan`,p1:`Le mot vient de 1812. Le gouverneur du Massachusetts Elbridge Gerry a approuvé une carte sénatoriale dont les circonscriptions étaient si tordues pour favoriser son parti qu'un caricaturiste bostonien en a dessiné une comme une salamandre — ailes, griffes, langue fourchue. Le jeu de mots du caricaturiste, <em>Gerry-mander</em>, est resté. La forme aussi : deux siècles plus tard, le mot signifie toujours tracer des limites électorales pour produire un résultat partisan.`,p2:`Le terme perdure parce que le problème perdure. Partout où les électeurs choisissent des représentants à partir de circonscriptions géographiques, quelqu'un doit tracer les limites, et les limites peuvent être tracées de plusieurs façons. Différents pays sont arrivés à différentes réponses sur qui devrait faire le tracé et ce qui devrait l'encadrer.`,p3:`<strong>Les États-Unis</strong> traitent le découpage partisan comme un problème que les tribunaux fédéraux ne peuvent généralement pas régler. Dans <em>Rucho v. Common Cause</em> (2019), la Cour suprême des États-Unis a statué que les découpages partisans sont des « questions politiques » qui échappent à sa compétence. Certains États (Californie, Michigan) ont réagi en créant des commissions citoyennes indépendantes pour tracer leurs propres limites ; d'autres (Texas, Caroline du Nord) ont continué à tracer des cartes ouvertement partisanes et les ont défendues en s'appuyant sur le fait que <em>Rucho</em> le permet.`,p4:`<strong>Le Royaume-Uni</strong> utilise quatre Commissions permanentes de délimitation — une pour l'Angleterre, l'Écosse, le Pays de Galles et l'Irlande du Nord — composées de juges et de hauts fonctionnaires. Elles retracent les limites tous les huit ans environ selon des règles fixes (égalité de population, cohérence géographique, respect des limites des administrations locales). Le Parlement peut en théorie rejeter les recommandations des commissions, mais dans la pratique ne le fait pratiquement jamais ; la convention veut que le jugement des commissions tienne.`,p5:`<strong>L'Australie</strong> délègue le travail à la Commission électorale australienne, une agence fédérale indépendante avec autorité complète sur l'administration des élections et sur les limites. Les redécoupages ont lieu automatiquement quand le nombre de sièges d'un État change ou que sept ans se sont écoulés depuis le dernier. Les décisions des commissaires peuvent être révisées sur des motifs procéduraux mais pas sur des motifs partisans. Comme au Royaume-Uni, le résultat est que le découpage partisan tel que les Américains le connaissent est pratiquement inconnu.`,p6:`Ces trois cas encadrent le spectre : tribunaux qui restent à l'écart (États-Unis), commissions indépendantes avec forte déférence parlementaire (Royaume-Uni), et agence indépendante permanente avec autorité complète (Australie). Le Canada se situe encore ailleurs — ce que la prochaine section aborde.`},editorial_canada:{heading:`Le Canada est différent — et semblable`,p1:`Le Canada appartient à la même famille que les États-Unis, le Royaume-Uni et l'Australie. Nous élisons des membres uniques à partir de circonscriptions géographiques selon le scrutin majoritaire uninominal. Nous retraçons les limites périodiquement — au fédéral après chaque recensement décennal, dans les provinces selon des calendriers échelonnés. Nous avons hérité de la machinerie de base des mêmes racines de Westminster. Jusqu'ici, aucune surprise.`,p2:`Ce qui distingue le Canada, c'est le critère que les limites doivent satisfaire.`,p3:`Dans le droit constitutionnel américain, la règle contraignante est <em>une personne, un vote</em> — les circonscriptions doivent avoir des populations aussi égales que possible, et les écarts importants exigent une justification stricte. Dans le droit constitutionnel canadien, la règle contraignante est différente. L'article 3 de la <em>Charte canadienne des droits et libertés</em> garantit à chaque citoyen le droit de vote. Dans le <em>Renvoi : Circonscriptions électorales provinciales (Sask.)</em> — le Renvoi de la Saskatchewan de 1991, l'arrêt de référence — la Cour suprême du Canada a interprété ce droit comme un droit à une <em>représentation effective</em>, et non comme un droit à l'égalité mathématique des populations de circonscriptions.`,p4:`Cette distinction compte. La représentation effective permet aux populations des circonscriptions de varier, parfois substantiellement, lorsqu'il y a de bonnes raisons : de vastes géographies rurales qu'un MLA ne peut raisonnablement desservir à une densité de population standard, des communautés d'intérêts qui doivent rester groupées, une représentation des minorités que l'égalité mathématique diluerait. Le Renvoi de la Saskatchewan a rendu cette flexibilité constitutionnelle. La variance de population de 25 % de la loi sur la délimitation électorale — la règle qui protège les sièges ruraux de l'Alberta — en découle directement.`,p5:`Le hic, c'est que la flexibilité fonctionne dans les deux sens. Si une commission peut légitimement s'écarter de l'égalité de population pour les bonnes raisons, elle peut aussi s'en écarter pour les mauvaises. Le droit canadien n'a pas de plancher mathématique à l'américaine sur lequel se rabattre. Il a le critère de représentation effective, appliqué par les juges, après coup, en cas de litige. La plupart des juridictions se prémunissent contre les mauvaises raisons avec des protections structurelles : les commissions fédérales de redécoupage sont isolées par la loi et leurs recommandations entrent en vigueur automatiquement si le Parlement n'agit pas dans un délai imparti. Le Québec utilise une commission permanente indépendante dont l'Assemblée nationale ne peut renverser le travail qu'à une majorité des deux tiers. La Colombie-Britannique fonctionne selon une règle d'adoption par défaut similaire.`,p6:`L'Alberta est l'exception. En vertu de la <em>Electoral Boundaries Commission Act</em>, le rapport de la commission n'est qu'une recommandation — l'assemblée législative doit voter pour l'adopter. C'est normalement une formalité. Dans le cycle 2026, la commission s'est divisée 3 contre 2 et a produit deux propositions concurrentes ; l'assemblée a créé un comité distinct de MLA, présidé par un MLA nommé par le Premier ministre, pour choisir entre elles. Rien dans le droit constitutionnel canadien n'exigeait que ce comité existe. Rien n'exige que son choix suive le processus de la commission. C'est la lacune structurelle que cet audit examine.`,p7:`Donc, quand les tribunaux canadiens disent que « découpage partisan » n'est pas leur vocabulaire juridique, ils ne disent pas que le concept sous-jacent ne s'applique pas ici. Ils disent que le critère est différent — représentation effective, et non égalité mathématique. Savoir si la proposition minoritaire répond à ce critère est exactement la question contre laquelle cet audit a mesuré la géométrie, et exactement la question à laquelle seul un juge peut répondre de façon définitive. Le raisonnement complet du <em>Renvoi de la Saskatchewan</em>, le contraste avec d'autres provinces, la question de la qualité pour agir et les voies de réforme disponibles sont traités dans <a href="#references">la section des références ci-dessous</a>.`}},tl:{selector:{label:`Pumili ng wika`},disclaimer:{text:`Isinalin ang site na ito sa pamamagitan ng AI. Maaaring may mga nilalamang nasa Ingles pa habang isinasagawa ang pagsasalin. Kung may mga mali o nais ninyong tumulong sa pagsasalin ng proyektong ito, mangyaring %s.`,link_label:`makipag-ugnayan sa amin`},opener:{heading:`Para kanino ito?`,body:`Para sa atin. Para sa ating lahat. Sa mga taga-bukid, sa mga taga-lungsod, sa mga curious, sa mga mahilig sa pulitika, sa mga mamamahayag, sa mga abugado, sa mga akademiko, sa mga pulitiko — para sa ating lahat. Dahil nakakaapekto ito sa ating lahat. Anuman ang iyong palagay sa partidong nasa poder, ang ginawa ng hating komisyon ay hindi pa nangyari noon. At binigyan tayo nito ng pagkakataong masilip ang loob ng makinarya sa paraang hindi pa natin nagawa. Ngayon ay maaari na tayong magtatag ng isang batayan — isang serye ng mga pagsusulit, at lahat ng susunod ay maaaring sukatin batay dito. Hayaan ninyong ipakita ko sa inyo ang aking natuklasan.`},stakes:{q1:{heading:`Ang iminungkahing mapa ba ay isang gerrymander?`,body:`Ang "gerrymander" ay hindi terminong ginagamit ng mga korte sa Canada. Ngunit kung gagamitin ito — sa pang-araw-araw na kahulugang ibinibigay ng karamihan — ang mga ebidensya sa audit na ito ay makatuwirang sumusuporta sa pagtawag sa <em>panukala ng minorya</em>, kung ito ay magiging batas, bilang isang mapa na malalim na gerrymandered. Lahat ng istrukturang pagsusulit ng audit na ito ay tumutukoy sa <em>panukala ng minorya</em>; wala ni isa ang tumutukoy sa kabilang panukala (ang <em>panukala ng mayorya</em>).`,footnote:`Ang mga pangalang "mayorya" at "minorya" ay galing sa 3–2 na paghahati sa Electoral Boundaries Commission (pinamumunuan ni Justice Miller), na nagprodyus ng dalawang nagtutunggaling panukala sa halip na isang rekomendasyon. Isang hiwalay na komite ng mga MLA na pinamumunuan ni Brandon Lunty — isang MLA na hinirang ng Premier — ang pumipili ngayon sa pagitan ng mga ito bago ang takdang petsa ng Nobyembre 2026.`},q2:{heading:`Ano ang ibig sabihin ng "gerrymander" sa batas ng Canada?`,body:`Wala. Iba ang pagsusuri ng Canada: kung binibigyan ng <em>epektibong representasyon</em> ang mga botante sa ilalim ng seksyon 3 ng Charter. Ang panukala ng minorya ay nagdudulot ng mga seryosong tanong sa ilalim ng pagsusuring iyon; isang hukom lamang ang makakasagot ng tiyak, at walang sinuman pa ang nagtanong sa kanya.`},q3:{heading:`Ano ang ibig sabihin nito para sa mga Albertan?`,body:`Sa isang 50/50 na boto sa probinsya, inilalagay ng mga sukat ng audit ang panukala ng minorya sa isang istrukturang sukdulan — mas mababa sa 100 ng 1.01 milyong neutral na mga mapa ng paghahambing ang nagbibigay ng kaparehong uri ng kawalan ng balanse sa upuan. Mahalaga ang kawalan ng balanseng iyon dahil sa 58 ng 87 upuan — isang dalawang-katlong supermayorya — ang naghaharing partido ay nakakakuha ng pambihirang mga kapangyarihang pamamaraan: maaari nitong tanggalin ang karaniwang mga panahon ng abiso at itulak ang mga panukalang batas sa pamamagitan ng maraming yugto ng pambabatasan sa isang araw lamang, lampas sa mga pagsusuri ng paglalapat na karaniwang nagpipigil sa kanya. Kung ang pagkakahilig ng panukala ng minorya ay sapat na laki upang itulak ang isang partido lampas sa hangganang 58-upuan sa mga sukat ng boto na <em>iba</em> sa 50/50 ay isang tanong na hindi pa sinuri ng audit na ito. Kung katanggap-tanggap ang pagpapalitan mismo ay isang tanong para sa mga Albertan, hindi para sa audit na ito.`},cta_law:`Basahin ang legal na konteksto →`,cta_methods:`Tingnan kung paano namin sinubukan →`},head:{title:`Pag-audit ng Hangganan ng Halalan sa Alberta`,meta_description:`Estadistikong pag-audit ng komisyon ng hangganan ng halalan sa Alberta sa 2026 — 1,010,000 neutral na mga mapa, opisyal na mga shapefile ng Elections Alberta, mga pre-registered na pagsusulit.`},nav:{home_aria:`Bumalik sa itaas`,theme_aria:`Palitan ang madilim / maliwanag na mode`,theme_title:`Palitan ang madilim na mode`,nav_aria:`I-toggle ang nabigasyon`,drawer_top:`↑ Itaas`,stakes:`Hatol`,why:`Bakit?`,map:`Mapa`,split:`Ang Paghahati`,litmus:`Pagsusulit`,crack_pack:`Crack at Pack`,for_you:`Para Sa Iyo`,impact:`Epekto`,history:`Kasaysayan`,canada:`Canada`,gerrymanders:`Mga Gerrymander`,november:`Nobyembre`,lunty:`Lunty`,invisible:`Hindi Nakikita`,suggestions:`Mga Mungkahi`,retractions:`Mga Pagbawi`,references:`Mga Sanggunian`,resources:`Mga Mapagkukunan`,technical:`Teknikal`},hero:{h1:`Pag-audit ng Hangganan ng Halalan sa Alberta`,subtitle:`Ang komisyon ng Alberta ay nagprodyus ng dalawang mapa ng riding sa 2026. Inihambing ng audit na ito ang mga ito — gamit ang parehong mga pagsusulit, na inilapat nang pantay sa pareho — upang itanong kung pareho nilang itinuturing ang mga botante.`,badge:`Mga opisyal na mapa ng Elections Alberta — Inilathala noong Mayo 2026`,cover_note:`I-click upang mag-zoom at galugarin ang lahat ng tatlong panukala ng hangganan nang sabay-sabay. I-pin ang viewport at mag-flip sa pagitan ng mga mapa — gumagalaw ang mga hangganan, nananatili ang mga botante. Mag-scroll pababa para sa pagsusuri.`,cover_note_1:`Ang mapang ito ang pinakamahusay na paraan upang magsimula. I-click ito upang mag-zoom at galugarin. Ang mga pindutan sa itaas ay nagpapalipat sa pagitan ng mapa ng minorya, mapa ng mayorya, at mga hangganan na nasaad noong 2019 — o ilatag ang lahat ng tatlo upang makita kung saan sila eksaktong nag-iiba. Kinukulayan ng <strong>Detail</strong> ang bawat polling area ayon sa paano bumoto ang mga tao noong 2023; nagdadagdag ang <strong>Trend</strong> ng partisan shading bawat distrito (asul UCP, kahel NDP); ginagawang on/off ng <strong>Lines</strong> ang mga hangganan. Ang <strong>Find</strong> ay lumulukso sa anumang riding ayon sa pangalan.`,cover_note_2:`Subukang i-lock ang viewport at mag-flip sa pagitan ng mga mapa — pagmasdan ang isang hangganan na lumilipat habang ang mga botante sa ilalim ay nananatiling tahimik. Iyon ang buong tanong sa isang galaw.`,cover_note_3:`Kapag tapos ka nang mag-explore, mag-scroll pababa para sa buod. Para sa kumpletong teknikal na pagsusuri, tingnan ang seksyon ng Mga Mapagkukunan. Lahat ng data ay mula sa opisyal na shapefile ng Elections Alberta at iba pang gobyerno at open-source na mga rekord.`,image_alt:`Mga mapa ng distritong pang-eleksyon sa Alberta — panukala ng minorya ng komisyon, kinulayan ayon sa boto noong 2023`,map_hint:`I-click upang galugarin nang interactive`,btn_title:`I-click upang buksan ang interactive na mapa`,btn_aria:`Buksan ang interactive na mapa`},editorial_intro:{heading:`Ano ang redistricting at bakit ito ay dapat mahalaga sa iyo?`,p1:`Ang bawat botante sa Alberta ay naninirahan sa isang <em>elektoral na distrito</em> — isang seksyon ng probinsya na pumipili ng isang tao sa lehislatura. May 87 distrito. Ang bawat distrito ay pumipili ng isang MLA. Kapag ikaw ay bumoboto sa isang elektoral na probinsya, pinipili mo ang MLA para sa distrito kung saan ka nakatira. Iyon ang buong koneksyon ng karamihan sa mga Albertan sa lehislatura: isang MLA, isang distrito, isang boto.`,p2:`Ang mga linyang ito ng distrito ay hindi permanente. Lumilipat ang mga tao, lumalago ang mga kapitbahayan, ang mga lugar sa kanayunan ay nagiging manipis, at ang mga lungsod ay lumalawak. Tuwing walo hanggang sampung taon, dapat na muling iguhit ng Alberta ang mga linya upang ang bawat distrito ay nasa tamang sukat at sumasalamin sa kung paano talaga nakatira ang mga Albertan ngayon. Ang katawan na muling gumuhit ay ang <em>Komisyon ng Hangganan ng Halalan</em> — isang independiyenteng komisyon na may mga huwes, abugado, at miyembro ng publiko, hindi mga politiko.`,p3:`Iyon ang karaniwang proseso. Sa pagkakataong ito, ang karaniwang proseso ay nagprodyus ng isang bagay na hindi karaniwan. Ang limang miyembro ng komisyon ay naghati-hati ng 3 sa 2 sa kung anong itsura ng mapa ay dapat, at sa halip na magkasundo sa isang rekomendasyon, sila ay nagprodyus ng dalawa: isang <em>panukala ng mayorya</em> (sinusuportahan ng tatlong komisyonado) at isang <em>panukala ng minorya</em> (sinusuportahan ng dalawa). Ang dalawa ay nakapatong sa mesa. Isang hiwalay na komite ng mga MLA na pinamumunuan ni Brandon Lunty — hinirang ng Premier para sa partikular na desisyong ito — ang pumipili sa pagitan ng mga ito. Ang lehislatura ay dapat aprubahan kung alin ang makakaligtas sa komiteng iyon bago ang Nobyembre 2026.`,p4:`Kung bakit ito mahalaga sa iyo: ang mga linya ay nagdedesisyon kung sino ang iyong MLA. Sila ang nagdedesisyon kung anong mga kapitbahayan, bayan, at alalahanin ang kinakatawan nang magkasama. Kung ang iyong lungsod ay nahahati sa apat na MLA sa halip na isa, walang iisang kinatawan ang may pananagutan para sa lungsod sa kabuuan. Kung ang iyong komunidad ng interes — isang maliit na bayan, isang rural na rehiyon, isang sentro ng lungsod — ay nahahati sa pagitan ng mga distrito, ang iyong boses sa mga desisyon ng probinsya ay nalalabnaw. Hinuhubog din ng mapa kung anong partido ang maaaring magtatag ng gobyerno, at sa anong margin. Ang partikular na natuklasan ng audit (na ang panukala ng minorya ay nasa isang sukdulan ng istraktura) ay ang dahilan kung bakit binabasa mo ang site na ito, ngunit ang mas malawak na tanong ay mas matanda at naaangkop sa bawat redistricting cycle: ang mga linya ba ay sumasalamin sa kung paano nakatira ang mga Albertan, o hinuhubog ba nila ang pulitika na susunod?`,p5:`Ang natitirang bahagi ng pahinang ito ay tumatakbo sa kung ano talaga ang ginagawa ng dalawang iminungkahing mapa.`,key_terms_lead:`Mga pangunahing termino sa seksyong ito — i-click upang basahin:`},boundary:{heading:`Kung ano ang masasabi at hindi masasabi ng audit na ito`,can_1:`Mas mababa sa 1 sa 14.5 milyong random na nilikhang mga mapa ng paghahambing ang nagprodyus ng mga pattern na kasinghirap ng panukala ng minorya sa lahat ng apat na estadistikong sukat na pinagsama.`,can_2:`Ang panukala ng minorya ay bumagsak sa 5 sa 5 pre-registered na istrukturang pagsusulit. Ang panukala ng mayorya ay bumagsak sa 0 sa 5.`,can_3:`Ang mga resultang ito ay tugma sa mga mapa na nagpoprodyus ng malalakas na epektong partisan, at hindi tugma sa kung ano ang prinopodyus ng random na set ng paghahambing.`,cant_1:`Ang audit ay <strong>hindi</strong> nagtatatag na anumang komisyonado ay may intensyon sa mga epektong partisan na sinusukat nito. Hindi maipakikita ng geometriya ng hangganan ang intensyon.`,cant_2:`Ang audit ay <strong>hindi</strong> humuhula kung ano ang pipiliin ng Lunty committee, kung ano ang magiging boto sa Nobyembre 2026, o kung paano magrereaksyon ang mga Albertan.`,cant_3:`Ang audit ay <strong>hindi</strong> humuhula kung paano huhusgahan ng isang korte kung magsasampa ng Charter challenge laban sa alinmang panukala.`,cant_4:`Ang audit ay <strong>hindi</strong> nagsasabi sa anumang indibidwal na botante kung anong posisyon ang dapat kunin o ano ang gagawin sa impormasyong ito. Sa inyo iyon na desisyon.`}},pa:{selector:{label:`ਭਾਸ਼ਾ ਚੁਣੋ`},disclaimer:{text:`ਇਸ ਸਾਈਟ ਦਾ ਅਨੁਵਾਦ AI ਦੁਆਰਾ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਨੁਵਾਦ ਚੱਲ ਰਹੇ ਹੋਣ ਦੌਰਾਨ ਕੁਝ ਸਮੱਗਰੀ ਅਜੇ ਵੀ ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਦਿਖਾਈ ਦੇ ਸਕਦੀ ਹੈ। ਜੇ ਤੁਸੀਂ ਗਲਤੀਆਂ ਦੇਖਦੇ ਹੋ ਜਾਂ ਇਸ ਪ੍ਰੋਜੈਕਟ ਦੇ ਅਨੁਵਾਦ ਵਿੱਚ ਮਦਦ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਕਿਰਪਾ ਕਰਕੇ %s।`,link_label:`ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ`},opener:{heading:`ਇਹ ਕਿਸ ਲਈ ਹੈ?`,body:`ਸਾਡੇ ਲਈ। ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਪੇਂਡੂ, ਸ਼ਹਿਰੀ, ਜਿਗਿਆਸੂ, ਸਿਆਸਤ ਦੇ ਸ਼ੁਕੀਨ, ਪੱਤਰਕਾਰ, ਵਕੀਲ, ਵਿਦਵਾਨ, ਚੁਣੇ ਹੋਏ ਨੁਮਾਇੰਦੇ — ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਕਿਉਂਕਿ ਇਹ ਸਾਨੂੰ ਸਾਰਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ। ਭਾਵੇਂ ਤੁਸੀਂ ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਨੂੰ ਪਸੰਦ ਕਰਦੇ ਹੋ ਜਾਂ ਨਹੀਂ, ਜੋ ਵੰਡੇ ਹੋਏ ਕਮਿਸ਼ਨ ਨੇ ਪੈਦਾ ਕੀਤਾ ਉਹ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਹੋਇਆ। ਅਤੇ ਇਸ ਨੇ ਸਾਨੂੰ ਇਸ ਮਸ਼ੀਨ ਦੇ ਅੰਦਰ ਝਾਤੀ ਮਾਰਨ ਦਾ ਮੌਕਾ ਦਿੱਤਾ ਹੈ ਜਿਸ ਤਰ੍ਹਾਂ ਅਸੀਂ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਮਾਰ ਸਕੇ। ਹੁਣ ਅਸੀਂ ਇੱਕ ਆਧਾਰ-ਰੇਖਾ ਸਥਾਪਤ ਕਰ ਸਕਦੇ ਹਾਂ — ਪਰੀਖਣਾਂ ਦੀ ਇੱਕ ਲੜੀ, ਅਤੇ ਜੋ ਕੁਝ ਵੀ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦਾ ਹੈ ਉਸਨੂੰ ਇਸ ਦੇ ਆਧਾਰ ਉੱਤੇ ਪਰਖਿਆ ਜਾ ਸਕਦਾ ਹੈ। ਮੈਨੂੰ ਤੁਹਾਨੂੰ ਦਿਖਾਉਣ ਦਿਓ ਕਿ ਮੈਂ ਕੀ ਲੱਭਿਆ ਹੈ।`},stakes:{q1:{heading:`ਕੀ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ਾ ਇੱਕ ਗੈਰੀਮੈਂਡਰ ਹੈ?`,body:`"ਗੈਰੀਮੈਂਡਰ" ਕੈਨੇਡੀਅਨ ਅਦਾਲਤਾਂ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਸ਼ਬਦ ਨਹੀਂ ਹੈ। ਪਰ ਜੇ ਇਹ ਹੁੰਦਾ — ਜਿਸ ਆਮ ਅਰਥ ਵਿੱਚ ਜ਼ਿਆਦਾਤਰ ਲੋਕ ਇਸਨੂੰ ਸਮਝਦੇ ਹਨ — ਤਾਂ ਇਸ ਆਡਿਟ ਦੇ ਸਬੂਤ ਮੁਨਾਸਬ ਤੌਰ ਤੇ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਨੂੰ, ਜੇ ਲਾਗੂ ਕੀਤਾ ਜਾਵੇ, ਇੱਕ ਡੂੰਘੀ ਗੈਰੀਮੈਂਡਰਡ ਨਕਸ਼ੇ ਵਜੋਂ ਕਹਿਣ ਦੀ ਹਮਾਇਤ ਕਰਨਗੇ। ਇਸ ਆਡਿਟ ਦੇ ਹਰ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣ ਵਿੱਚ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਚਿੰਨ੍ਹਿਤ ਹੁੰਦੀ ਹੈ; ਕੋਈ ਵੀ ਬਦਲ (<em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em>) ਨੂੰ ਚਿੰਨ੍ਹਿਤ ਨਹੀਂ ਕਰਦਾ।`,footnote:`"ਬਹੁ-ਗਿਣਤੀ" ਅਤੇ "ਘੱਟ-ਗਿਣਤੀ" ਨਾਂ ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ (ਜਸਟਿਸ ਮਿਲਰ ਦੀ ਪ੍ਰਧਾਨਗੀ ਅਧੀਨ) ਵਿੱਚ 3–2 ਦੀ ਵੰਡ ਤੋਂ ਆਏ ਹਨ, ਜਿਸ ਨੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਦੀ ਬਜਾਏ ਦੋ ਮੁਕਾਬਲੇ ਵਾਲੀਆਂ ਪ੍ਰਸਤਾਵਾਂ ਪੈਦਾ ਕੀਤੀਆਂ। ਬ੍ਰੈਂਡਨ ਲੰਟੀ — ਪ੍ਰੀਮੀਅਰ ਦੁਆਰਾ ਨਿਯੁਕਤ ਇੱਕ MLA — ਦੀ ਪ੍ਰਧਾਨਗੀ ਵਾਲੀ ਇੱਕ ਵੱਖਰੀ MLA ਕਮੇਟੀ ਨਵੰਬਰ 2026 ਦੀ ਆਖਰੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਇਹਨਾਂ ਵਿਚਕਾਰ ਚੋਣ ਕਰ ਰਹੀ ਹੈ।`},q2:{heading:`ਕੈਨੇਡੀਅਨ ਕਾਨੂੰਨ ਵਿੱਚ "ਗੈਰੀਮੈਂਡਰ" ਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`ਕੁਝ ਨਹੀਂ। ਕੈਨੇਡੀਅਨ ਪਰੀਖਣ ਵੱਖਰਾ ਹੈ: ਕੀ ਸਰਹੱਦਾਂ ਚਾਰਟਰ ਦੀ ਧਾਰਾ 3 ਦੇ ਅਧੀਨ ਵੋਟਰਾਂ ਨੂੰ <em>ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਪ੍ਰਤੀਨਿਧਤਾ</em> ਦਿੰਦੀਆਂ ਹਨ। ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇਸ ਪਰੀਖਣ ਅਧੀਨ ਗੰਭੀਰ ਸਵਾਲ ਖੜੇ ਕਰਦੀ ਹੈ; ਸਿਰਫ਼ ਇੱਕ ਜੱਜ ਹੀ ਉਨ੍ਹਾਂ ਦਾ ਨਿਸ਼ਚਿਤ ਜਵਾਬ ਦੇ ਸਕਦਾ ਹੈ, ਅਤੇ ਅਜੇ ਤੱਕ ਕਿਸੇ ਨੇ ਨਹੀਂ ਪੁੱਛਿਆ।`},q3:{heading:`ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਇਸਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`50/50 ਸੂਬਾਈ ਵੋਟ ਉੱਤੇ, ਆਡਿਟ ਦੇ ਮਾਪ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਨੂੰ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਰੱਖਦੇ ਹਨ — 1.01 ਮਿਲੀਅਨ ਨਿਰਪੱਖ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 100 ਤੋਂ ਘੱਟ ਉਸੇ ਕਿਸਮ ਦਾ ਸੀਟ ਅਸੰਤੁਲਨ ਪੈਦਾ ਕਰਦੇ ਹਨ। ਉਹ ਅਸੰਤੁਲਨ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਕਿਉਂਕਿ 87 ਵਿੱਚੋਂ 58 ਸੀਟਾਂ ਉੱਤੇ — ਦੋ ਤਿਹਾਈ ਸੁਪਰ-ਬਹੁਮਤ — ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਅਸਾਧਾਰਨ ਪ੍ਰਕਿਰਿਆਤਮਕ ਸ਼ਕਤੀਆਂ ਖੋਲ੍ਹਦੀ ਹੈ: ਇਹ ਨੋਟਿਸ ਦੀਆਂ ਮਾਨਕ ਮਿਆਦਾਂ ਨੂੰ ਛੱਡ ਸਕਦੀ ਹੈ ਅਤੇ ਜਨਤਕ ਬਿੱਲਾਂ ਨੂੰ ਇੱਕ ਹੀ ਦਿਨ ਵਿੱਚ ਕਈ ਵਿਧਾਨਕ ਪੜਾਵਾਂ ਰਾਹੀਂ ਅੱਗੇ ਧੱਕ ਸਕਦੀ ਹੈ, ਉਨ੍ਹਾਂ ਵਿਚਾਰ-ਵਟਾਂਦਰੇ ਦੀਆਂ ਜਾਂਚਾਂ ਨੂੰ ਟਪਾ ਕੇ ਜੋ ਆਮ ਤੌਰ ਤੇ ਇਸਨੂੰ ਸੀਮਤ ਕਰਦੀਆਂ ਹਨ। ਕੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਦਾ ਝੁਕਾਅ 50/50 ਤੋਂ <em>ਇਲਾਵਾ</em> ਹੋਰ ਵੋਟ ਅਨੁਪਾਤਾਂ ਉੱਤੇ ਇੱਕ ਪਾਰਟੀ ਨੂੰ 58-ਸੀਟਾਂ ਦੀ ਹੱਦ ਤੋਂ ਪਾਰ ਧੱਕਣ ਲਈ ਕਾਫ਼ੀ ਵੱਡਾ ਹੈ, ਇਹ ਇੱਕ ਸਵਾਲ ਹੈ ਜਿਸਨੂੰ ਇਹ ਆਡਿਟ ਅਜੇ ਤੱਕ ਨਹੀਂ ਪਰਖ ਸਕਿਆ। ਕੀ ਇਹ ਅਦਲਾ-ਬਦਲੀ ਆਪਣੇ ਆਪ ਵਿੱਚ ਸਵੀਕਾਰਯੋਗ ਹੈ, ਇਹ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਸਵਾਲ ਹੈ, ਇਸ ਆਡਿਟ ਲਈ ਨਹੀਂ।`},cta_law:`ਕਾਨੂੰਨੀ ਸੰਦਰਭ ਪੜ੍ਹੋ →`,cta_methods:`ਦੇਖੋ ਅਸੀਂ ਕਿਵੇਂ ਪਰਖਿਆ →`},head:{title:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,meta_description:`ਅਲਬਰਟਾ ਦੇ 2026 ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ ਦਾ ਅੰਕੜਾ ਆਡਿਟ — 1,010,000 ਨਿਰਪੱਖ ਨਕਸ਼ੇ, ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ, ਪੂਰਵ-ਰਜਿਸਟਰਡ ਪਰੀਖਣ।`},nav:{home_aria:`ਉੱਪਰ ਵਾਪਸ ਜਾਓ`,theme_aria:`ਡਾਰਕ / ਲਾਈਟ ਮੋਡ ਬਦਲੋ`,theme_title:`ਡਾਰਕ ਮੋਡ ਬਦਲੋ`,nav_aria:`ਨੇਵੀਗੇਸ਼ਨ ਟੌਗਲ ਕਰੋ`,drawer_top:`↑ ਉੱਪਰ`,stakes:`ਫੈਸਲਾ`,why:`ਕਿਉਂ?`,map:`ਨਕਸ਼ਾ`,split:`ਵੰਡ`,litmus:`ਪਰਖ`,crack_pack:`ਫੁੱਟ ਤੇ ਪੈਕ`,for_you:`ਤੁਹਾਡੇ ਲਈ`,impact:`ਅਸਰ`,history:`ਇਤਿਹਾਸ`,canada:`ਕੈਨੇਡਾ`,gerrymanders:`ਗੈਰੀਮੈਂਡਰ`,november:`ਨਵੰਬਰ`,lunty:`ਲੰਟੀ`,invisible:`ਅਦ੍ਰਿਸ਼`,suggestions:`ਸੁਝਾਅ`,retractions:`ਵਾਪਸੀਆਂ`,references:`ਹਵਾਲੇ`,resources:`ਸਰੋਤ`,technical:`ਤਕਨੀਕੀ`},hero:{h1:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,subtitle:`ਅਲਬਰਟਾ ਦੇ ਕਮਿਸ਼ਨ ਨੇ 2026 ਵਿੱਚ ਦੋ ਰਾਈਡਿੰਗ ਨਕਸ਼ੇ ਪੈਦਾ ਕੀਤੇ। ਇਸ ਆਡਿਟ ਨੇ ਉਹਨਾਂ ਦੀ ਤੁਲਨਾ ਕੀਤੀ — ਉਹੀ ਪਰੀਖਣ ਵਰਤਦੇ ਹੋਏ, ਦੋਵਾਂ ਉੱਤੇ ਬਰਾਬਰ ਲਾਗੂ ਕੀਤੇ — ਇਹ ਪੁੱਛਣ ਲਈ ਕਿ ਕੀ ਉਹ ਵੋਟਰਾਂ ਨਾਲ ਇੱਕੋ ਜਿਹਾ ਸਲੂਕ ਕਰਦੇ ਹਨ।`,badge:`ਅਧਿਕਾਰਤ Elections Alberta ਨਕਸ਼ੇ — ਮਈ 2026 ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਿਤ`,cover_note:`ਤਿੰਨੇ ਸਰਹੱਦ ਪ੍ਰਸਤਾਵਾਂ ਨੂੰ ਇੱਕੋ ਸਮੇਂ ਜ਼ੂਮ ਕਰਨ ਅਤੇ ਖੋਜਣ ਲਈ ਕਲਿੱਕ ਕਰੋ। ਵਿਊਪੋਰਟ ਪਿੰਨ ਕਰੋ ਅਤੇ ਨਕਸ਼ਿਆਂ ਵਿਚਕਾਰ ਫਲਿੱਪ ਕਰੋ — ਸਰਹੱਦਾਂ ਖਿਸਕਦੀਆਂ ਹਨ, ਵੋਟਰ ਆਪਣੀ ਥਾਂ ਰਹਿੰਦੇ ਹਨ। ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ।`,cover_note_1:`ਇਹ ਨਕਸ਼ਾ ਅੰਦਰ ਆਉਣ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਰਾਹ ਹੈ। ਜ਼ੂਮ ਕਰਨ ਅਤੇ ਖੋਜਣ ਲਈ ਇਸ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ। ਉੱਪਰਲੇ ਬਟਨ ਘੱਟ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਬਹੁ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਅਤੇ 2019 ਵਿੱਚ ਲਾਗੂ ਕੀਤੀਆਂ ਸਰਹੱਦਾਂ ਵਿਚਕਾਰ ਬਦਲਦੇ ਹਨ — ਜਾਂ ਤਿੰਨੋਂ ਨੂੰ ਲੇਅਰ ਕਰੋ ਇਹ ਦੇਖਣ ਲਈ ਕਿ ਉਹ ਕਿੱਥੇ ਠੀਕ ਨਾਲ ਵੱਖ ਹੁੰਦੇ ਹਨ। <strong>Detail</strong> ਹਰ ਪੋਲਿੰਗ ਖੇਤਰ ਨੂੰ 2023 ਵਿੱਚ ਲੋਕਾਂ ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗਦਾ ਹੈ; <strong>Trend</strong> ਜ਼ਿਲ੍ਹੇ ਅਨੁਸਾਰ ਪਾਰਟੀ ਛਾਂ ਜੋੜਦਾ ਹੈ (ਨੀਲਾ UCP, ਸੰਤਰੀ NDP); <strong>Lines</strong> ਸਰਹੱਦਾਂ ਨੂੰ ਚਾਲੂ-ਬੰਦ ਕਰਦਾ ਹੈ। <strong>Find</strong> ਨਾਮ ਅਨੁਸਾਰ ਕਿਸੇ ਵੀ ਰਾਈਡਿੰਗ ਉੱਤੇ ਪਹੁੰਚਦਾ ਹੈ।`,cover_note_2:`ਵਿਊਪੋਰਟ ਨੂੰ ਲਾਕ ਕਰਕੇ ਨਕਸ਼ਿਆਂ ਵਿਚਕਾਰ ਬਦਲਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ — ਦੇਖੋ ਕਿਵੇਂ ਸਰਹੱਦ ਖਿਸਕਦੀ ਹੈ ਜਦੋਂ ਕਿ ਹੇਠਾਂ ਦੇ ਵੋਟਰ ਉੱਥੇ ਹੀ ਰਹਿੰਦੇ ਹਨ। ਇਹ ਇੱਕ ਇਸ਼ਾਰੇ ਵਿੱਚ ਸਾਰਾ ਸਵਾਲ ਹੈ।`,cover_note_3:`ਜਦੋਂ ਤੁਹਾਡੀ ਖੋਜ ਮੁਕੰਮਲ ਹੋ ਜਾਵੇ, ਸੰਖੇਪ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ। ਪੂਰੇ ਤਕਨੀਕੀ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਸਰੋਤ ਸੈਕਸ਼ਨ ਦੇਖੋ। ਸਾਰਾ ਡੇਟਾ ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ ਅਤੇ ਹੋਰ ਸਰਕਾਰੀ ਅਤੇ ਓਪਨ-ਸੋਰਸ ਰਿਕਾਰਡਾਂ ਤੋਂ ਹੈ।`,image_alt:`ਅਲਬਰਟਾ ਦੇ ਚੋਣ ਜ਼ਿਲ੍ਹਾ ਨਕਸ਼ੇ — ਕਮਿਸ਼ਨ ਦੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ, 2023 ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗੀ`,map_hint:`ਇੰਟਰਐਕਟਿਵ ਤੌਰ ਤੇ ਖੋਜਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_title:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_aria:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹੋ`},editorial_intro:{heading:`ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਕੀ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਇਸ ਦੀ ਪਰਵਾਹ ਕਿਉਂ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ?`,p1:`ਅਲਬਰਟਾ ਦਾ ਹਰ ਵੋਟਰ ਇੱਕ <em>ਚੋਣ ਜ਼ਿਲ੍ਹੇ</em> ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ — ਸੂਬੇ ਦਾ ਇੱਕ ਹਿੱਸਾ ਜੋ ਵਿਧਾਨ ਸਭਾ ਲਈ ਇੱਕ ਵਿਅਕਤੀ ਨੂੰ ਚੁਣਦਾ ਹੈ। 87 ਜ਼ਿਲ੍ਹੇ ਹਨ। ਹਰ ਜ਼ਿਲ੍ਹਾ ਇੱਕ MLA ਚੁਣਦਾ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਸੂਬਾਈ ਚੋਣ ਵਿੱਚ ਵੋਟ ਪਾਉਂਦੇ ਹੋ, ਤੁਸੀਂ ਉਸ ਜ਼ਿਲ੍ਹੇ ਲਈ MLA ਚੁਣ ਰਹੇ ਹੋ ਜਿਸ ਵਿੱਚ ਤੁਸੀਂ ਰਹਿੰਦੇ ਹੋ। ਜ਼ਿਆਦਾਤਰ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਦਾ ਵਿਧਾਨ ਸਭਾ ਨਾਲ ਪੂਰਾ ਸੰਪਰਕ ਇਹੀ ਹੈ: ਇੱਕ MLA, ਇੱਕ ਜ਼ਿਲ੍ਹਾ, ਇੱਕ ਵੋਟ।`,p2:`ਇਹ ਜ਼ਿਲ੍ਹੇ ਦੀਆਂ ਲਾਈਨਾਂ ਸਥਾਈ ਨਹੀਂ ਹਨ। ਲੋਕ ਚਲੇ ਜਾਂਦੇ ਹਨ, ਮੁਹੱਲੇ ਵੱਡੇ ਹੁੰਦੇ ਹਨ, ਪੇਂਡੂ ਖੇਤਰ ਖਾਲੀ ਹੁੰਦੇ ਹਨ, ਸ਼ਹਿਰ ਫੈਲਦੇ ਹਨ। ਹਰ ਅੱਠ ਤੋਂ ਦਸ ਸਾਲਾਂ ਬਾਅਦ, ਅਲਬਰਟਾ ਨੂੰ ਲਾਈਨਾਂ ਨੂੰ ਮੁੜ ਖਿੱਚਣਾ ਚਾਹੀਦਾ ਹੈ ਤਾਂ ਜੋ ਹਰ ਜ਼ਿਲ੍ਹਾ ਲਗਭਗ ਸਹੀ ਆਕਾਰ ਦਾ ਹੋਵੇ ਅਤੇ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰੇ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਅਸਲ ਵਿੱਚ ਹੁਣ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ। ਮੁੜ-ਖਿੱਚਣ ਵਾਲੀ ਸੰਸਥਾ <em>ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ</em> ਹੈ — ਜੱਜਾਂ, ਵਕੀਲਾਂ, ਅਤੇ ਜਨਤਕ ਮੈਂਬਰਾਂ ਦਾ ਇੱਕ ਸੁਤੰਤਰ ਕਮਿਸ਼ਨ, ਨਾ ਕਿ ਸਿਆਸਤਦਾਨਾਂ ਦਾ।`,p3:`ਇਹੀ ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਹੈ। ਇਸ ਵਾਰ, ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਨੇ ਕੁਝ ਅਸਾਧਾਰਨ ਪੈਦਾ ਕੀਤਾ। ਕਮਿਸ਼ਨ ਦੇ ਪੰਜ ਮੈਂਬਰ 3 ਬਨਾਮ 2 ਵਿੱਚ ਵੰਡੇ ਗਏ ਕਿ ਨਕਸ਼ੇ ਨੂੰ ਕਿਹੋ ਜਿਹਾ ਦਿਖਣਾ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਉੱਤੇ ਸਹਿਮਤ ਹੋਣ ਦੀ ਬਜਾਏ ਉਹਨਾਂ ਨੇ ਦੋ ਤਿਆਰ ਕੀਤੀਆਂ: ਇੱਕ <em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਤਿੰਨ ਕਮਿਸ਼ਨਰਾਂ ਦੁਆਰਾ ਸਮਰਥਨ) ਅਤੇ ਇੱਕ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਦੋਆਂ ਦੁਆਰਾ ਸਮਰਥਨ)। ਦੋਵੇਂ ਮੇਜ਼ ਉੱਤੇ ਹਨ। ਬ੍ਰੈਂਡਨ ਲੰਟੀ ਦੀ ਅਗਵਾਈ ਵਾਲੀ MLA ਦੀ ਇੱਕ ਵੱਖਰੀ ਕਮੇਟੀ — ਜਿਸਨੂੰ ਪ੍ਰੀਮੀਅਰ ਨੇ ਇਸ ਖਾਸ ਫੈਸਲੇ ਲਈ ਨਿਯੁਕਤ ਕੀਤਾ — ਉਨ੍ਹਾਂ ਵਿਚਕਾਰ ਚੋਣ ਕਰ ਰਹੀ ਹੈ। ਨਵੰਬਰ 2026 ਤੋਂ ਪਹਿਲਾਂ ਵਿਧਾਨ ਸਭਾ ਨੂੰ ਉਸ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣੀ ਚਾਹੀਦੀ ਹੈ ਜੋ ਉਸ ਕਮੇਟੀ ਤੋਂ ਬਚ ਜਾਂਦੀ ਹੈ।`,p4:`ਇਹ ਤੁਹਾਡੇ ਲਈ ਕਿਉਂ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ: ਲਾਈਨਾਂ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਤੁਹਾਡਾ MLA ਕੌਣ ਹੈ। ਉਹ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਕਿਹੜੇ ਮੁਹੱਲੇ, ਕਸਬੇ, ਅਤੇ ਚਿੰਤਾਵਾਂ ਇਕੱਠੇ ਪ੍ਰਤੀਨਿਧਤਾ ਪ੍ਰਾਪਤ ਕਰਦੀਆਂ ਹਨ। ਜੇ ਤੁਹਾਡਾ ਸ਼ਹਿਰ ਇੱਕ ਦੀ ਥਾਂ ਚਾਰ MLAs ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਕੋਈ ਇੱਕ ਨੁਮਾਇੰਦਾ ਪੂਰੇ ਸ਼ਹਿਰ ਲਈ ਜਵਾਬਦੇਹ ਨਹੀਂ ਹੈ। ਜੇ ਤੁਹਾਡਾ ਹਿੱਤ ਸਮੁਦਾਇ — ਇੱਕ ਛੋਟਾ ਕਸਬਾ, ਇੱਕ ਪੇਂਡੂ ਖੇਤਰ, ਇੱਕ ਡਾਊਨਟਾਊਨ ਕੋਰ — ਜ਼ਿਲ੍ਹਿਆਂ ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਸੂਬਾਈ ਫੈਸਲਿਆਂ ਉੱਤੇ ਤੁਹਾਡੀ ਆਵਾਜ਼ ਪਤਲੀ ਹੁੰਦੀ ਹੈ। ਨਕਸ਼ਾ ਇਹ ਵੀ ਆਕਾਰ ਦਿੰਦਾ ਹੈ ਕਿ ਕਿਹੜੀ ਪਾਰਟੀ ਸਰਕਾਰ ਬਣਾ ਸਕਦੀ ਹੈ, ਅਤੇ ਕਿਸ ਮਾਰਜਨ ਨਾਲ। ਆਡਿਟ ਦੀ ਖਾਸ ਖੋਜ (ਕਿ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਬੈਠੀ ਹੈ) ਉਹ ਕਾਰਨ ਹੈ ਜੋ ਤੁਸੀਂ ਇਸ ਸਾਈਟ ਨੂੰ ਪੜ੍ਹ ਰਹੇ ਹੋ, ਪਰ ਵਿਆਪਕ ਸਵਾਲ ਪੁਰਾਣਾ ਹੈ ਅਤੇ ਹਰ ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਚੱਕਰ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ: ਕੀ ਲਾਈਨਾਂ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰਦੀਆਂ ਹਨ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ, ਜਾਂ ਉਹ ਉਸ ਰਾਜਨੀਤੀ ਨੂੰ ਆਕਾਰ ਦਿੰਦੀਆਂ ਹਨ ਜੋ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦੀ ਹੈ?`,p5:`ਇਸ ਪੰਨੇ ਦਾ ਬਾਕੀ ਹਿੱਸਾ ਇਸ ਦੇ ਪਾਰ ਚੱਲਦਾ ਹੈ ਕਿ ਦੋ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ੇ ਅਸਲ ਵਿੱਚ ਕੀ ਕਰਦੇ ਹਨ।`,key_terms_lead:`ਇਸ ਸੈਕਸ਼ਨ ਦੇ ਮੁੱਖ ਸ਼ਬਦ — ਪੜ੍ਹਨ ਲਈ ਕਲਿੱਕ ਕਰੋ:`},boundary:{heading:`ਇਹ ਆਡਿਟ ਤੁਹਾਨੂੰ ਕੀ ਦੱਸ ਸਕਦਾ ਹੈ ਅਤੇ ਕੀ ਨਹੀਂ`,can_1:`1.45 ਕਰੋੜ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 1 ਤੋਂ ਘੱਟ ਨੇ ਚਾਰੇ ਅੰਕੜਾ ਮਾਪਾਂ ਨੂੰ ਮਿਲਾ ਕੇ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਜਿੰਨੇ ਅਤਿਅੰਤ ਨਮੂਨੇ ਪੈਦਾ ਕੀਤੇ।`,can_2:`ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ 5 ਵਿੱਚੋਂ 5 ਪੂਰਵ-ਰਜਿਸਟਰਡ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣਾਂ ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ। ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ 5 ਵਿੱਚੋਂ 0 ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ।`,can_3:`ਇਹ ਨਤੀਜੇ ਉਹਨਾਂ ਨਕਸ਼ਿਆਂ ਨਾਲ ਮੇਲ ਖਾਂਦੇ ਹਨ ਜੋ ਮਜ਼ਬੂਤ ਪਾਰਟੀ ਪ੍ਰਭਾਵ ਪੈਦਾ ਕਰਦੇ ਹਨ, ਅਤੇ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਸੈੱਟ ਦੇ ਉਤਪਾਦਨ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ।`,cant_1:`ਆਡਿਟ ਇਹ ਸਥਾਪਤ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਕਿਸੇ ਕਮਿਸ਼ਨਰ ਨੇ ਉਹਨਾਂ ਪਾਰਟੀ ਪ੍ਰਭਾਵਾਂ ਦੀ ਨੀਅਤ ਰੱਖੀ ਜੋ ਇਹ ਮਾਪਦਾ ਹੈ। ਸਰਹੱਦੀ ਜਿਓਮੈਟਰੀ ਨੀਅਤ ਨੂੰ ਪ੍ਰਗਟ ਨਹੀਂ ਕਰ ਸਕਦੀ।`,cant_2:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਲੰਟੀ ਕਮੇਟੀ ਕੀ ਚੁਣੇਗੀ, ਨਵੰਬਰ 2026 ਦੀ ਵੋਟ ਕੀ ਹੋਵੇਗੀ, ਜਾਂ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਪ੍ਰਤੀਕਿਰਿਆ ਕਰਨਗੇ।`,cant_3:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਜੇ ਕਿਸੇ ਪ੍ਰਸਤਾਵ ਖਿਲਾਫ਼ ਚਾਰਟਰ ਚੁਣੌਤੀ ਦਾਇਰ ਕੀਤੀ ਜਾਂਦੀ ਤਾਂ ਅਦਾਲਤ ਕਿਵੇਂ ਫੈਸਲਾ ਕਰੇਗੀ।`,cant_4:`ਆਡਿਟ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀਗਤ ਵੋਟਰ ਨੂੰ ਇਹ <strong>ਨਹੀਂ</strong> ਦੱਸਦਾ ਕਿ ਕੀ ਪੋਜੀਸ਼ਨ ਲਵੇ ਜਾਂ ਇਸ ਜਾਣਕਾਰੀ ਨਾਲ ਕੀ ਕਰੇ। ਇਹ ਫੈਸਲਾ ਤੁਹਾਡਾ ਹੈ।`}},"zh-Hans":{selector:{label:`选择语言`},disclaimer:{text:`本网站由 AI 翻译。在翻译进行期间,部分内容可能仍以英文显示。如果您发现错误或希望帮助翻译本项目,请%s。`,link_label:`联系我们`},opener:{heading:`这是为谁准备的?`,body:`为我们。为我们所有人。无论你是乡村居民、城市居民、好奇者、政治爱好者、记者、律师、学者还是政治人物——我们所有人。因为这影响着我们所有人。无论你是否喜欢执政党,分裂的委员会所产生的结果是前所未有的。它给了我们一个前所未有的机会,得以窥视这台机器的内部运作。现在我们可以建立一个基准——一系列测试,之后的一切都可以以此为标准进行评估。让我向你展示我所发现的。`},stakes:{q1:{heading:`所提议的地图是否构成选区不公?`,body:`"Gerrymander"(选区不公划分)并非加拿大法院使用的术语。但如果以普通人理解的日常意义来衡量——本次审计的证据合理地支持将<em>少数派提议</em>(若被采纳)称为一份严重经过党派划分的地图。本次审计运行的每一项结构性测试都标记了<em>少数派提议</em>;没有任何一项测试标记了另一份提议(<em>多数派提议</em>)。`,footnote:`"多数派"和"少数派"的称谓源自选举边界委员会(由 Miller 法官主持)内部 3 比 2 的分裂——该委员会未能形成单一建议,而是提出了两份相互竞争的提议。一个由 Brandon Lunty(由省长任命的 MLA)主持的独立 MLA 委员会正在于 2026 年 11 月截止日期前在两者之间作出选择。`},q2:{heading:`"Gerrymander" 在加拿大法律中是什么意思?`,body:`没有意义。加拿大的检验标准不同:即边界是否在《宪章》第3条之下给予选民<em>有效代表权</em>。少数派提议在该标准下提出了严重问题;只有法官才能给出确定性的回答,而目前尚无人提起诉讼。`},q3:{heading:`这对阿尔伯塔人意味着什么?`,body:`在50/50的省级投票情况下,审计的测量将少数派提议置于结构性极端——在101万张中立比较地图中,产生类似议席不平衡的不到100张。这种不平衡之所以重要,是因为在87席中获得58席——即三分之二的超级多数——执政党便解锁了非常规的程序权力:它可以免除标准通知期,并在一天内将公共法案推过多个立法阶段,绕过通常约束它的审议性检查。少数派提议的倾斜是否大到足以在<em>非</em>50/50的投票比例下将一个政党推过58席门槛,这是本次审计尚未测试的问题。这种取舍本身是否可接受,这是属于阿尔伯塔人的问题,而非本次审计的问题。`},cta_law:`阅读法律背景 →`,cta_methods:`查看我们如何测试 →`},head:{title:`阿尔伯塔选举边界审计`,meta_description:`对阿尔伯塔2026年选举边界委员会的统计审计——101万张中立地图、Elections Alberta官方shapefile、预先注册的测试。`},nav:{home_aria:`返回顶部`,theme_aria:`切换深色 / 浅色模式`,theme_title:`切换深色模式`,nav_aria:`切换导航`,drawer_top:`↑ 顶部`,stakes:`结论`,why:`为什么?`,map:`地图`,split:`分裂`,litmus:`试金石`,crack_pack:`分散与集中`,for_you:`对你而言`,impact:`影响`,history:`历史`,canada:`加拿大`,gerrymanders:`选区操控`,november:`十一月`,lunty:`Lunty`,invisible:`隐形`,suggestions:`建议`,retractions:`撤回`,references:`参考资料`,resources:`资源`,technical:`技术`},hero:{h1:`阿尔伯塔选举边界审计`,subtitle:`阿尔伯塔的委员会在2026年提出了两份选区地图。本次审计对它们进行了比较——使用相同的测试,平等地应用于两者——以询问它们是否以同样的方式对待选民。`,badge:`Elections Alberta 官方地图——2026年5月发布`,cover_note:`点击同时缩放和探索所有三份边界提议。固定视口并在地图之间切换——边界移动,选民保持不变。向下滚动查看分析。`,cover_note_1:`这张地图是最好的入口。点击它即可缩放和探索。顶部按钮可在少数派地图、多数派地图和2019年颁布的边界之间切换——或叠加三者以查看它们的分歧之处。<strong>Detail</strong> 根据2023年人们的投票情况为每个投票区上色;<strong>Trend</strong> 按选区添加党派色调(蓝色UCP,橙色NDP);<strong>Lines</strong> 切换边界的开关。<strong>Find</strong> 按名称跳转到任何选区。`,cover_note_2:`尝试锁定视图并在地图之间切换——观察一条边界在下方选民保持不动时如何移动。这就是整个问题,用一个动作表达。`,cover_note_3:`当您探索完毕后,向下滚动查看摘要。如需完整的技术分析,请参阅"资源"部分。所有数据均来自 Elections Alberta 官方shapefile以及其他政府和开源记录。`,image_alt:`阿尔伯塔选区地图——委员会少数派提议,按2023年投票上色`,map_hint:`点击进行交互式探索`,btn_title:`点击打开交互式地图`,btn_aria:`打开交互式地图`},editorial_intro:{heading:`什么是选区划分,以及为什么你应该关心?`,p1:`阿尔伯塔的每位选民都生活在一个<em>选区</em>中——省份的一个切片,负责选出一位省议会议员。共有87个选区。每个选区选出一位MLA。当你在省级选举中投票时,你是在为你所居住的选区选出MLA。这就是大多数阿尔伯塔人与立法机构的全部联系:一位MLA,一个选区,一票。`,p2:`这些选区界线并非永久。人会搬家,社区会扩大,乡村会变少,城市会扩张。每隔八到十年,阿尔伯塔应该重新划界,使每个选区大致大小合适,并反映阿尔伯塔人现在实际的居住情况。负责重新划界的机构是<em>选举边界委员会</em>——一个由法官、律师和公众成员组成的独立委员会,而非政客。`,p3:`那是标准程序。这一次,标准程序产生了不寻常的结果。委员会的五名成员就地图应是什么样子分裂成了3比2,与其达成一项建议,他们提出了两份:一份<em>多数派提议</em>(由三位委员支持)和一份<em>少数派提议</em>(由两位支持)。两份都摆在桌上。一个由Brandon Lunty主持的独立MLA委员会——由省长为此特定决定任命——正在两者之间作出选择。立法机构必须在2026年11月之前批准在该委员会中存活下来的那一份。`,p4:`为什么这对你重要:这些界线决定了谁是你的MLA。它们决定了哪些社区、城镇和关切被一起代表。如果你的城市被切分到四位MLA而不是一位,没有任何一位代表对整个城市负责。如果你的利益共同体——一个小镇、一个乡村地区、一个市中心——被划分到不同的选区,你在省级决策中的声音被稀释。这张地图还塑造了哪个政党能组建政府,以及以何种边际。本次审计的具体发现(少数派提议处于结构性极端)是你正在阅读本网站的原因,但更广泛的问题更古老,适用于每一个选区重划周期:这些界线反映了阿尔伯塔人的实际居住方式,还是塑造了之后的政治?`,p5:`本页的其余部分将讲解这两份提议地图实际上做了什么。`,key_terms_lead:`本节关键术语 — 点击阅读:`},boundary:{heading:`本次审计能告诉你什么,不能告诉你什么`,can_1:`在1450万张随机生成的比较地图中,少数派提议在所有四项统计指标综合方面所产生的极端模式不到1张。`,can_2:`少数派提议在5项预先注册的结构性测试中全部失败。多数派提议在5项中失败0项。`,can_3:`这些结果与产生强烈党派效应的地图一致,与随机比较集所产生的结果不一致。`,cant_1:`本次审计<strong>未能</strong>证明任何委员有意制造其所测量的党派效应。边界几何无法揭示意图。`,cant_2:`本次审计<strong>不</strong>预测 Lunty 委员会会做出什么选择,2026 年 11 月投票结果如何,或阿尔伯塔人会如何反应。`,cant_3:`本次审计<strong>不</strong>预测如果对任一提议提起《宪章》诉讼,法院将如何裁决。`,cant_4:`本次审计<strong>不</strong>告诉任何选民应采取什么立场或如何处理这些信息。这是由你决定的。`}},"zh-Hant":{selector:{label:`選擇語言`},disclaimer:{text:`本網站由 AI 翻譯。在翻譯進行期間,部分內容可能仍以英文顯示。如果您發現錯誤或希望幫助翻譯本項目,請%s。`,link_label:`聯絡我們`},opener:{heading:`這是為誰準備的?`,body:`為我們。為我們所有人。無論你是鄉村居民、城市居民、好奇者、政治愛好者、記者、律師、學者還是政治人物——我們所有人。因為這影響著我們所有人。無論你是否喜歡執政黨,分裂的委員會所產生的結果是前所未有的。它給了我們一個前所未有的機會,得以窺視這台機器的內部運作。現在我們可以建立一個基準——一系列測試,之後的一切都可以以此為標準進行評估。讓我向你展示我所發現的。`},stakes:{q1:{heading:`所提議的地圖是否構成選區不公?`,body:`「Gerrymander」(選區不公劃分)並非加拿大法院使用的術語。但如果以普通人理解的日常意義來衡量——本次審計的證據合理地支持將<em>少數派提議</em>(若被採納)稱為一份嚴重經過黨派劃分的地圖。本次審計運行的每一項結構性測試都標記了<em>少數派提議</em>;沒有任何一項測試標記了另一份提議(<em>多數派提議</em>)。`,footnote:`「多數派」和「少數派」的稱謂源自選舉邊界委員會(由 Miller 法官主持)內部 3 比 2 的分裂——該委員會未能形成單一建議,而是提出了兩份相互競爭的提議。一個由 Brandon Lunty(由省長任命的 MLA)主持的獨立 MLA 委員會正在於 2026 年 11 月截止日期前在兩者之間作出選擇。`},q2:{heading:`「Gerrymander」在加拿大法律中是什麼意思?`,body:`沒有意義。加拿大的檢驗標準不同:即邊界是否在《憲章》第3條之下給予選民<em>有效代表權</em>。少數派提議在該標準下提出了嚴重問題;只有法官才能給出確定性的回答,而目前尚無人提起訴訟。`},q3:{heading:`這對阿爾伯塔人意味著什麼?`,body:`在50/50的省級投票情況下,審計的測量將少數派提議置於結構性極端——在101萬張中立比較地圖中,產生類似議席不平衡的不到100張。這種不平衡之所以重要,是因為在87席中獲得58席——即三分之二的超級多數——執政黨便解鎖了非常規的程序權力:它可以免除標準通知期,並在一天內將公共法案推過多個立法階段,繞過通常約束它的審議性檢查。少數派提議的傾斜是否大到足以在<em>非</em>50/50的投票比例下將一個政黨推過58席門檻,這是本次審計尚未測試的問題。這種取捨本身是否可接受,這是屬於阿爾伯塔人的問題,而非本次審計的問題。`},cta_law:`閱讀法律背景 →`,cta_methods:`查看我們如何測試 →`},head:{title:`阿爾伯塔選舉邊界審計`,meta_description:`對阿爾伯塔2026年選舉邊界委員會的統計審計——101萬張中立地圖、Elections Alberta官方shapefile、預先註冊的測試。`},nav:{home_aria:`返回頂部`,theme_aria:`切換深色 / 淺色模式`,theme_title:`切換深色模式`,nav_aria:`切換導覽`,drawer_top:`↑ 頂部`,stakes:`結論`,why:`為什麼?`,map:`地圖`,split:`分裂`,litmus:`試金石`,crack_pack:`分散與集中`,for_you:`對你而言`,impact:`影響`,history:`歷史`,canada:`加拿大`,gerrymanders:`選區操控`,november:`十一月`,lunty:`Lunty`,invisible:`隱形`,suggestions:`建議`,retractions:`撤回`,references:`參考資料`,resources:`資源`,technical:`技術`},hero:{h1:`阿爾伯塔選舉邊界審計`,subtitle:`阿爾伯塔的委員會在2026年提出了兩份選區地圖。本次審計對它們進行了比較——使用相同的測試,平等地應用於兩者——以詢問它們是否以同樣的方式對待選民。`,badge:`Elections Alberta 官方地圖——2026年5月發佈`,cover_note:`點擊同時縮放和探索所有三份邊界提議。固定視口並在地圖之間切換——邊界移動,選民保持不變。向下捲動查看分析。`,cover_note_1:`這張地圖是最好的入口。點擊它即可縮放和探索。頂部按鈕可在少數派地圖、多數派地圖和2019年頒布的邊界之間切換——或疊加三者以查看它們的分歧之處。<strong>Detail</strong> 根據2023年人們的投票情況為每個投票區上色;<strong>Trend</strong> 按選區添加黨派色調(藍色UCP,橙色NDP);<strong>Lines</strong> 切換邊界的開關。<strong>Find</strong> 按名稱跳轉到任何選區。`,cover_note_2:`嘗試鎖定視圖並在地圖之間切換——觀察一條邊界在下方選民保持不動時如何移動。這就是整個問題,用一個動作表達。`,cover_note_3:`當您探索完畢後,向下滾動查看摘要。如需完整的技術分析,請參閱「資源」部分。所有數據均來自 Elections Alberta 官方shapefile以及其他政府和開源記錄。`,image_alt:`阿爾伯塔選區地圖——委員會少數派提議,按2023年投票上色`,map_hint:`點擊進行互動式探索`,btn_title:`點擊打開互動式地圖`,btn_aria:`打開互動式地圖`},editorial_intro:{heading:`什麼是選區劃分,以及為什麼你應該關心?`,p1:`阿爾伯塔的每位選民都生活在一個<em>選區</em>中——省份的一個切片,負責選出一位省議會議員。共有87個選區。每個選區選出一位MLA。當你在省級選舉中投票時,你是在為你所居住的選區選出MLA。這就是大多數阿爾伯塔人與立法機構的全部聯繫:一位MLA,一個選區,一票。`,p2:`這些選區界線並非永久。人會搬家,社區會擴大,鄉村會變少,城市會擴張。每隔八到十年,阿爾伯塔應該重新劃界,使每個選區大致大小合適,並反映阿爾伯塔人現在實際的居住情況。負責重新劃界的機構是<em>選舉邊界委員會</em>——一個由法官、律師和公眾成員組成的獨立委員會,而非政客。`,p3:`那是標準程序。這一次,標準程序產生了不尋常的結果。委員會的五名成員就地圖應是什麼樣子分裂成了3比2,與其達成一項建議,他們提出了兩份:一份<em>多數派提議</em>(由三位委員支持)和一份<em>少數派提議</em>(由兩位支持)。兩份都擺在桌上。一個由Brandon Lunty主持的獨立MLA委員會——由省長為此特定決定任命——正在兩者之間作出選擇。立法機構必須在2026年11月之前批准在該委員會中存活下來的那一份。`,p4:`為什麼這對你重要:這些界線決定了誰是你的MLA。它們決定了哪些社區、城鎮和關切被一起代表。如果你的城市被切分到四位MLA而不是一位,沒有任何一位代表對整個城市負責。如果你的利益共同體——一個小鎮、一個鄉村地區、一個市中心——被劃分到不同的選區,你在省級決策中的聲音被稀釋。這張地圖還塑造了哪個政黨能組建政府,以及以何種邊際。本次審計的具體發現(少數派提議處於結構性極端)是你正在閱讀本網站的原因,但更廣泛的問題更古老,適用於每一個選區重劃週期:這些界線反映了阿爾伯塔人的實際居住方式,還是塑造了之後的政治?`,p5:`本頁的其餘部分將講解這兩份提議地圖實際上做了什麼。`,key_terms_lead:`本節關鍵術語 — 點擊閱讀:`},boundary:{heading:`本次審計能告訴你什麼,不能告訴你什麼`,can_1:`在1450萬張隨機生成的比較地圖中,少數派提議在所有四項統計指標綜合方面所產生的極端模式不到1張。`,can_2:`少數派提議在5項預先註冊的結構性測試中全部失敗。多數派提議在5項中失敗0項。`,can_3:`這些結果與產生強烈黨派效應的地圖一致,與隨機比較集所產生的結果不一致。`,cant_1:`本次審計<strong>未能</strong>證明任何委員有意製造其所測量的黨派效應。邊界幾何無法揭示意圖。`,cant_2:`本次審計<strong>不</strong>預測 Lunty 委員會會做出什麼選擇,2026 年 11 月投票結果如何,或阿爾伯塔人會如何反應。`,cant_3:`本次審計<strong>不</strong>預測如果對任一提議提起《憲章》訴訟,法院將如何裁決。`,cant_4:`本次審計<strong>不</strong>告訴任何選民應採取什麼立場或如何處理這些信息。這是由你決定的。`}}};function m(e,t){let n=e;for(let e of t.split(`.`))if(n&&typeof n==`object`&&e in n)n=n[e];else return;return n}function h(e,t){let n=m(p[e],t);if(typeof n==`string`)return n;let r=m(p.en,t);return typeof r==`string`?r:`[missing:${t}]`}export{d as a,f as i,i as n,r,h as t};